  q('hc-L5-025','healthcare',5,25,'warm-up','Hospital Diagnostic panels Standard Pricing Index (CTE)','Dr. Anthony Clark','Director of Pathology & Lab',
    'Laboratory price list benchmark: Using a CTE, calculate the minimum standard fee, maximum standard fee, and average fee for lab tests in each category. Return category, test count, min fee, max fee, and avg fee.',
    'WITH lab_pricing AS (...) SELECT category, test_count, min_fee, max_fee, avg_fee.',['WITH CTE','GROUP BY','MIN','MAX','AVG'],['category','test_count','min_fee','max_fee','avg_fee'],
    "WITH lab_pricing AS (SELECT category, COUNT(id) AS test_count, ROUND(MIN(standard_fee), 2) AS min_fee, ROUND(MAX(standard_fee), 2) AS max_fee, ROUND(AVG(standard_fee), 2) AS avg_fee FROM lab_tests GROUP BY category) SELECT category, test_count, min_fee, max_fee, avg_fee FROM lab_pricing ORDER BY avg_fee DESC;",'t',
    ['Compute min, max, avg fee per category in CTE.','Select category, test_count, min_fee, max_fee, avg_fee.'],'Benchmarks price ranges across pathology divisions.',35,7),

  // 26–50: Core (Multi-Stage CTE Pipelines, Service Line P&L, Clinical Lifecycle Tracing)
  q('hc-L5-026','healthcare',5,26,'core','Comprehensive Hospital Outpatient Service Line P&L (Multi-Stage CTE)','Jordan Chen','Director of Billing',
    'Department outpatient financial scorecard: Construct a 2-stage CTE pipeline. In Stage 1, calculate completed appointment count, total visit revenue, and total doctors per department. In Stage 2, compute revenue per doctor. Return department name, completed visits, doctors count, total revenue, and revenue per doctor.',
    'WITH dept_appts AS (...), dept_docs AS (...) SELECT department_name, visits, doctors, revenue, rev_per_doc.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','ARITHMETIC'],['department_name','completed_visits','doctors_count','total_revenue','revenue_per_doctor'],
    "WITH dept_appts AS (SELECT d.id AS department_id, d.name AS department_name, COUNT(a.id) AS completed_visits, ROUND(SUM(a.fee), 2) AS total_revenue FROM departments d JOIN doctors doc ON d.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id WHERE a.status = 'completed' GROUP BY d.id, d.name), dept_docs AS (SELECT department_id, COUNT(id) AS doctors_count FROM doctors GROUP BY department_id) SELECT a.department_name, a.completed_visits, d.doctors_count, a.total_revenue, ROUND(a.total_revenue / NULLIF(d.doctors_count, 0), 2) AS revenue_per_doctor FROM dept_appts a JOIN dept_docs d ON a.department_id = d.department_id ORDER BY a.total_revenue DESC;",'t',
    ['Aggregate completed appointments in dept_appts.','Count doctors per department in dept_docs.','Join and calculate revenue_per_doctor.'],'Executive department service line P&L measuring clinical revenue productivity per staffed physician.',40,10),

  q('hc-L5-027','healthcare',5,27,'core','Hospital Inpatient Accommodation Revenue Yield (Multi-Stage CTE)','Marcus Thorne','Chief Nursing Officer',
    'Inpatient capacity monetization: Using a 2-stage CTE, calculate total rooms, total occupied beds, and daily realized room revenue (occupied rooms * rate) per building location. Return building, total rooms, occupied rooms, occupancy pct, and daily realized revenue.',
    'WITH room_counts AS (...) SELECT building, total_rooms, occupied_rooms, occupancy_pct, realized_revenue.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['building','total_rooms','occupied_rooms','occupancy_pct','realized_revenue'],
    "WITH room_stats AS (SELECT d.building, COUNT(r.id) AS total_rooms, SUM(CASE WHEN r.is_occupied THEN 1 ELSE 0 END) AS occupied_rooms, ROUND(SUM(CASE WHEN r.is_occupied THEN r.daily_rate ELSE 0 END), 2) AS realized_revenue FROM rooms r JOIN departments d ON r.department_id = d.id GROUP BY d.building) SELECT building, total_rooms, occupied_rooms, ROUND(occupied_rooms::NUMERIC / NULLIF(total_rooms, 0) * 100.0, 1) AS occupancy_pct, realized_revenue FROM room_stats ORDER BY realized_revenue DESC;",'t',
    ['Compute rooms, occupied beds, and realized revenue per building in CTE.','Calculate occupancy percentage in outer query.'],'Tracks inpatient room occupancy monetization across physical hospital towers.',40,9),

  q('hc-L5-028','healthcare',5,28,'core','Payer Net Realization vs Contractual Denial Scorecard (Multi-Stage CTE)','Jordan Chen','Director of Billing',
    'Payer adjudication matrix: Using a 2-stage CTE, calculate gross claim dollars, approved dollars, and denied claims count for each insurance carrier. In Stage 2, calculate net realization percentage and denial percentage. Return carrier, gross claims, net approved, realization pct, and denial pct.',
    'WITH payer_claims AS (...) SELECT insurance_provider, gross_claim, net_approved, realization_pct, denial_pct.',['WITH CTE','GROUP BY','SUM','ROUND'],['insurance_provider','gross_claim','net_approved','realization_pct','denial_pct'],
    "WITH payer_raw AS (SELECT insurance_provider, COUNT(id) AS total_claims, ROUND(SUM(claim_amount), 2) AS gross_claim, ROUND(SUM(approved_amount), 2) AS net_approved, SUM(CASE WHEN status = 'denied' THEN 1 ELSE 0 END) AS denied_count FROM insurance_claims GROUP BY insurance_provider) SELECT insurance_provider, gross_claim, net_approved, ROUND(net_approved / NULLIF(gross_claim, 0) * 100.0, 1) AS realization_pct, ROUND(denied_count::NUMERIC / NULLIF(total_claims, 0) * 100.0, 1) AS denial_pct FROM payer_raw ORDER BY realization_pct DESC;",'t',
    ['Compute claim sums and denied count per payer in CTE.','Calculate realization and denial percentages in outer query.'],'Payer scorecard benchmarking contractual yield and administrative friction.',40,10),

  q('hc-L5-029','healthcare',5,29,'core','Patient 360: Clinical Encounters, Diagnoses & Lab Volume (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Longitudinal patient summary: Using multi-stage CTEs, compute completed appointments count, diagnoses count, and lab tests count for each patient. Return patient first name, last name, completed visits, diagnoses count, and lab tests count.',
    'WITH appts AS (...), diags AS (...), labs AS (...) SELECT first_name, last_name, visits, diags, labs.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY'],['first_name','last_name','completed_visits','diagnoses_count','lab_tests_count'],
    "WITH appts AS (SELECT patient_id, COUNT(id) AS completed_visits FROM appointments WHERE status = 'completed' GROUP BY patient_id), diags AS (SELECT patient_id, COUNT(id) AS diagnoses_count FROM diagnoses GROUP BY patient_id), labs AS (SELECT patient_id, COUNT(id) AS lab_tests_count FROM patient_lab_results GROUP BY patient_id) SELECT p.first_name, p.last_name, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(d.diagnoses_count, 0) AS diagnoses_count, COALESCE(l.lab_tests_count, 0) AS lab_tests_count FROM patients p LEFT JOIN appts a ON p.id = a.patient_id LEFT JOIN diags d ON p.id = d.patient_id LEFT JOIN labs l ON p.id = l.patient_id ORDER BY completed_visits DESC, diagnoses_count DESC LIMIT 25;",'t',
    ['Aggregate encounters across 3 CTEs (appointments, diagnoses, lab results).','Join to patients table with COALESCE.','Order by completed_visits DESC LIMIT 25.'],'Integrated patient 360 overview uniting clinical outpatient visits, diagnoses, and diagnostic labs.',40,11),

  q('hc-L5-030','healthcare',5,30,'core','Physician Comprehensive Outpatient Billing & Prescribing Scorecard (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Physician 360 evaluation: Using multi-stage CTEs, compute total completed appointments, gross appointment revenue, and total prescriptions written per doctor. Return doctor name, specialty, completed visits, gross revenue, and total prescriptions.',
    'WITH doc_appts AS (...), doc_rxs AS (...) SELECT name, specialty, completed_visits, gross_revenue, total_prescriptions.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY'],['name','specialty','completed_visits','gross_revenue','total_prescriptions'],
    "WITH doc_appts AS (SELECT doctor_id, COUNT(id) AS completed_visits, ROUND(SUM(fee), 2) AS gross_revenue FROM appointments WHERE status = 'completed' GROUP BY doctor_id), doc_rxs AS (SELECT doctor_id, COUNT(id) AS total_prescriptions FROM prescriptions GROUP BY doctor_id) SELECT d.name, d.specialty, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(a.gross_revenue, 0.00) AS gross_revenue, COALESCE(r.total_prescriptions, 0) AS total_prescriptions FROM doctors d LEFT JOIN doc_appts a ON d.id = a.doctor_id LEFT JOIN doc_rxs r ON d.id = r.doctor_id ORDER BY gross_revenue DESC, total_prescriptions DESC;",'t',
    ['Compute visit revenue and prescriptions in dual CTEs.','Join to doctors table.','Order by gross_revenue DESC.'],'Clinical practice balance sheet tracking consultation productivity and pharmacotherapy authorization.',40,10),

  q('hc-L5-031','healthcare',5,31,'core','Hospital Total Inpatient Bed Days and Occupancy Rate (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Inpatient utilization census: Using a CTE, calculate total inpatient admissions, total cumulative bed days (discharge_date - admission_date), and average length of stay per admitting doctor. Return doctor name, specialty, total admissions, and total bed days.',
    'WITH adm_stats AS (...) SELECT doc.name, doc.specialty, adm.admissions_count, adm.total_bed_days.',['WITH CTE','INNER JOIN','GROUP BY','SUM'],['name','specialty','admissions_count','total_bed_days','avg_stay_days'],
    "WITH adm_stats AS (SELECT admitting_doctor_id, COUNT(id) AS admissions_count, SUM(discharge_date - admission_date) AS total_bed_days, ROUND(AVG(discharge_date - admission_date), 1) AS avg_stay_days FROM inpatient_admissions WHERE discharge_date IS NOT NULL GROUP BY admitting_doctor_id) SELECT d.name, d.specialty, a.admissions_count, a.total_bed_days, a.avg_stay_days FROM doctors d JOIN adm_stats a ON d.id = a.admitting_doctor_id ORDER BY a.total_bed_days DESC;",'t',
    ['Calculate admissions and length of stay per admitting doctor in CTE.','Join to doctors and order by total_bed_days DESC.'],'Measures physician inpatient bed utilization impact across surgical and medical services.',40,9),

  q('hc-L5-032','healthcare',5,32,'core','Clinical Diagnostic Prevalence vs Prescription Adherence (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Care gap surveillance: Using multi-stage CTEs, count how many patients have received an ICD-10 diagnosis code vs how many have received a prescription for that condition. Return ICD-10 code, diagnosis description, and total diagnosed cases.',
    'WITH diag_cases AS (...) SELECT icd10_code, description, diagnosed_patients.',['WITH CTE','GROUP BY','COUNT DISTINCT'],['icd10_code','description','diagnosed_patients'],
    "WITH diag_cases AS (SELECT icd10_code, description, COUNT(DISTINCT patient_id) AS diagnosed_patients FROM diagnoses GROUP BY icd10_code, description) SELECT icd10_code, description, diagnosed_patients FROM diag_cases ORDER BY diagnosed_patients DESC;",'t',
    ['Aggregate diagnosed patients per ICD code in CTE.','Select icd10_code, description, diagnosed_patients.'],'Epidemiological foundation for monitoring clinical chronic disease management.',40,8),

  q('hc-L5-033','healthcare',5,33,'core','Accounts Receivable Outstanding Balances by Patient City (CTE)','Jordan Chen','Director of Billing',
    'Community financial exposure: Using a CTE, calculate total billed charges, total insurance covered, and total patient balance owed across all patient cities. Return city, total billed, insurance covered, and patient balance.',
    'WITH city_ar AS (...) SELECT city, total_billed, total_insurance_covered, total_patient_balance.',['WITH CTE','INNER JOIN','GROUP BY','SUM'],['city','total_billed','total_insurance_covered','total_patient_balance'],
    "WITH city_ar AS (SELECT p.city, ROUND(SUM(b.total_charge), 2) AS total_billed, ROUND(SUM(b.insurance_covered), 2) AS total_insurance_covered, ROUND(SUM(b.patient_balance), 2) AS total_patient_balance FROM billing b JOIN patients p ON b.patient_id = p.id GROUP BY p.city) SELECT city, total_billed, total_insurance_covered, total_patient_balance FROM city_ar ORDER BY total_patient_balance DESC;",'t',
    ['Join billing to patients in CTE.','Sum total_charge, insurance_covered, and patient_balance per city.'],'Evaluates community health system financial receivables and self-pay burden.',40,8),

  q('hc-L5-034','healthcare',5,34,'core','Operating Room Capacity and Procedural Cost by Floor (Multi-Stage CTE)','Dr. Sarah Patel','Head of Surgery',
    'Campus surgical facilities: Using a multi-stage CTE, calculate total surgical procedures, total procedural duration minutes, and total procedural cost for each hospital floor. Return building, floor, procedure count, and total cost.',
    'WITH dept_procs AS (...) SELECT building, floor, procedure_count, total_cost.',['WITH CTE','INNER JOIN','GROUP BY','SUM'],['building','floor','procedure_count','total_cost'],
    "WITH dept_procs AS (SELECT d.building, d.floor, COUNT(p.id) AS procedure_count, ROUND(SUM(p.standard_cost), 2) AS total_cost FROM departments d JOIN medical_procedures p ON d.id = p.department_id GROUP BY d.building, d.floor) SELECT building, floor, procedure_count, total_cost FROM dept_procs ORDER BY total_cost DESC;",'t',
    ['Join departments to medical_procedures in CTE.','Aggregate by building and floor.'],'Maps procedural throughput and infrastructure cost across hospital facilities.',40,8),

  q('hc-L5-035','healthcare',5,35,'core','Top Revenue Generating Doctors by Department (ROW_NUMBER CTE)','Jordan Chen','Director of Billing',
    'Department clinical leadership: Using a CTE with ROW_NUMBER, find the single highest completed revenue generating doctor in each department. Return department name, doctor name, completed visits, and gross revenue.',
    'WITH doc_rev AS (...) SELECT department_name, doctor_name, completed_visits, gross_revenue WHERE rn = 1.',['WITH CTE','ROW_NUMBER','PARTITION BY','INNER JOIN','GROUP BY'],['department_name','doctor_name','completed_visits','gross_revenue'],
    "WITH doc_rev AS (SELECT dept.name AS department_name, doc.name AS doctor_name, COUNT(a.id) AS completed_visits, ROUND(SUM(a.fee), 2) AS gross_revenue, ROW_NUMBER() OVER (PARTITION BY dept.id ORDER BY SUM(a.fee) DESC) AS rn FROM departments dept JOIN doctors doc ON dept.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id WHERE a.status = 'completed' GROUP BY dept.id, dept.name, doc.id, doc.name) SELECT department_name, doctor_name, completed_visits, gross_revenue FROM doc_rev WHERE rn = 1 ORDER BY gross_revenue DESC;",'t',
    ['Compute revenue and rank with ROW_NUMBER() partitioned by department in CTE.','Filter rn = 1 in outer query.'],'Surfaces premier clinical revenue leaders across every hospital department.',40,9),

  q('hc-L5-036','healthcare',5,36,'core','Patient Incurred Hospital Charges Stratification (NTILE CTE)','Jordan Chen','Director of Billing',
    'Patient financial segmentation: Using a CTE, aggregate total billed charges per patient, then divide patients into 4 financial liability quartiles using NTILE(4). Return patient_id, total billed, and quartile tier.',
    'WITH pt_totals AS (...) SELECT patient_id, total_billed, NTILE(4) OVER (ORDER BY total_billed DESC).',['WITH CTE','NTILE','GROUP BY','SUM'],['patient_id','total_billed','liability_quartile'],
    "WITH pt_totals AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_billed FROM billing GROUP BY patient_id) SELECT patient_id, total_billed, NTILE(4) OVER (ORDER BY total_billed DESC) AS liability_quartile FROM pt_totals ORDER BY liability_quartile, total_billed DESC;",'t',
    ['Sum total_charge per patient in CTE.','Apply NTILE(4) OVER (ORDER BY total_billed DESC) in outer query.'],'Classifies patient population into 4 financial liability tiers for credit risk analysis.',40,8),

  q('hc-L5-037','healthcare',5,37,'core','Pathology Diagnostic Panel Turnaround and Volume (CTE)','Dr. Anthony Clark','Director of Pathology & Lab',
    'Laboratory activity review: Using a CTE, compute total tests ordered, abnormal result flags count, and total standard fee billing potential for each diagnostic category. Return category, tests ordered, abnormal count, and gross billing potential.',
    'WITH lab_summary AS (...) SELECT category, tests_ordered, abnormal_count, gross_billing_potential.',['WITH CTE','INNER JOIN','GROUP BY','SUM'],['category','tests_ordered','abnormal_count','gross_billing_potential'],
    "WITH lab_summary AS (SELECT lt.category, COUNT(plr.id) AS tests_ordered, SUM(CASE WHEN plr.flag IN ('HIGH', 'LOW') THEN 1 ELSE 0 END) AS abnormal_count, ROUND(SUM(lt.standard_fee), 2) AS gross_billing_potential FROM lab_tests lt LEFT JOIN patient_lab_results plr ON lt.id = plr.test_id GROUP BY lt.category) SELECT category, tests_ordered, abnormal_count, gross_billing_potential FROM lab_summary ORDER BY gross_billing_potential DESC;",'t',
    ['Aggregate tests, abnormal flags, and standard fee potential per category in CTE.','Order by gross_billing_potential DESC.'],'Evaluates laboratory test volumes and diagnostic service billing yield.',40,8),

  q('hc-L5-038','healthcare',5,38,'core','Department Nurse-to-Patient Appointment Load Ratio (Multi-Stage CTE)','Marcus Thorne','Chief Nursing Officer',
    'Staffing workload balance: Using a multi-stage CTE, count completed appointments and total staffed nurses in each department. Calculate the appointments-per-nurse workload ratio. Return department name, completed visits, nurse count, and visits per nurse.',
    'WITH appts AS (...), nurses_count AS (...) SELECT department_name, visits, nurses, visits_per_nurse.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','ARITHMETIC'],['department_name','completed_visits','nurses_count','visits_per_nurse'],
    "WITH appts AS (SELECT d.id AS department_id, d.name AS department_name, COUNT(a.id) AS completed_visits FROM departments d JOIN doctors doc ON d.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id WHERE a.status = 'completed' GROUP BY d.id, d.name), nurses_count AS (SELECT department_id, COUNT(id) AS nurse_count FROM nurses GROUP BY department_id) SELECT a.department_name, a.completed_visits, n.nurse_count AS nurses_count, ROUND(a.completed_visits::NUMERIC / NULLIF(n.nurse_count, 0), 1) AS visits_per_nurse FROM appts a JOIN nurses_count n ON a.department_id = n.department_id ORDER BY visits_per_nurse DESC;",'t',
    ['Compute completed appointments and nurse count per department in dual CTEs.','Calculate visits_per_nurse ratio.'],'Evaluates nursing workload strain relative to outpatient clinical throughput.',40,9),

  q('hc-L5-039','healthcare',5,39,'core','Insurance Claims Settlement Delay Outliers (CTE)','Jordan Chen','Director of Billing',
    'Adjudication latency audit: Using a CTE that computes average settlement days per insurance provider, identify claims that took strictly longer than their provider average plus 5 days. Return claim id, insurance provider, settlement days, and provider avg settlement days.',
    'WITH payer_avg AS (...) SELECT c.id, c.insurance_provider, c.settlement_days, p.avg_days WHERE settlement_days > avg_days + 5.',['WITH CTE','INNER JOIN','WHERE','ARITHMETIC'],['id','insurance_provider','settlement_days','avg_settlement_days'],
    "WITH payer_avg AS (SELECT insurance_provider, ROUND(AVG(settlement_days), 1) AS avg_settlement_days FROM insurance_claims GROUP BY insurance_provider) SELECT c.id, c.insurance_provider, c.settlement_days, p.avg_settlement_days FROM insurance_claims c JOIN payer_avg p ON c.insurance_provider = p.insurance_provider WHERE c.settlement_days > (p.avg_settlement_days + 5) ORDER BY c.settlement_days DESC;",'t',
    ['Compute average settlement days per provider in CTE.','Filter claims where settlement_days > avg_settlement_days + 5.'],'Isolates severe claim adjudication delays exceeding health plan benchmarks.',40,9),

  q('hc-L5-040','healthcare',5,40,'core','Clinical Diagnostic Acuity Breakdown per Hospital Department (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Department clinical complexity index: Using a CTE, count mild, moderate, and severe diagnoses for each department. Compute the severe case percentage. Return department name, severe count, total diagnoses, and severe case pct.',
    'WITH dept_diags AS (...) SELECT department_name, severe_count, total_diagnoses, severe_case_pct.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['department_name','severe_count','total_diagnoses','severe_case_pct'],
    "WITH dept_diags AS (SELECT dept.name AS department_name, SUM(CASE WHEN dg.severity = 'Severe' THEN 1 ELSE 0 END) AS severe_count, COUNT(dg.id) AS total_diagnoses FROM departments dept JOIN doctors doc ON dept.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id JOIN diagnoses dg ON a.id = dg.appointment_id GROUP BY dept.id, dept.name) SELECT department_name, severe_count, total_diagnoses, ROUND(severe_count::NUMERIC / NULLIF(total_diagnoses, 0) * 100.0, 1) AS severe_case_pct FROM dept_diags ORDER BY severe_case_pct DESC, severe_count DESC;",'t',
    ['Aggregate severe and total diagnoses per department in CTE.','Compute severe percentage in outer query.'],'Assesses case-mix acuity across hospital clinical divisions.',40,9),

  q('hc-L5-041','healthcare',5,41,'core','Most Frequent Clinical Diagnoses with Average Incurred Bill (CTE)','Jordan Chen','Director of Billing',
    'Diagnosis financial footprint: Using a CTE that links diagnoses to billing via appointments, compute total recorded cases and average total billed charge for each ICD-10 diagnosis. Return ICD-10 code, description, case count, and average charge.',
    'WITH diag_billing AS (...) SELECT icd10_code, description, case_count, avg_charge.',['WITH CTE','INNER JOIN','GROUP BY','AVG'],['icd10_code','description','case_count','avg_charge'],
    "WITH diag_billing AS (SELECT dg.icd10_code, dg.description, COUNT(dg.id) AS case_count, ROUND(AVG(b.total_charge), 2) AS avg_charge FROM diagnoses dg JOIN billing b ON dg.appointment_id = b.appointment_id GROUP BY dg.icd10_code, dg.description) SELECT icd10_code, description, case_count, avg_charge FROM diag_billing ORDER BY case_count DESC, avg_charge DESC;",'t',
    ['Join diagnoses to billing in CTE.','Group by ICD code and description, computing count and avg charge.'],'Links clinical disease prevalence directly to encounter financial charges.',40,9),

  q('hc-L5-042','healthcare',5,42,'core','Hospital Inpatient Bed Occupancy Revenue Potential (CTE)','Marcus Thorne','Chief Nursing Officer',
    'Bed capacity economics: Using a CTE, calculate total rooms, total occupied rooms, and currently realized daily revenue (occupied rooms * rate) per room type. Return room type, total rooms, occupied rooms, and daily realized revenue.',
    'WITH room_type_stats AS (...) SELECT room_type, total_rooms, occupied_rooms, daily_revenue.',['WITH CTE','GROUP BY','SUM CASE'],['room_type','total_rooms','occupied_rooms','daily_revenue'],
    "WITH room_type_stats AS (SELECT room_type, COUNT(id) AS total_rooms, SUM(CASE WHEN is_occupied THEN 1 ELSE 0 END) AS occupied_rooms, ROUND(SUM(CASE WHEN is_occupied THEN daily_rate ELSE 0 END), 2) AS daily_revenue FROM rooms GROUP BY room_type) SELECT room_type, total_rooms, occupied_rooms, daily_revenue FROM room_type_stats ORDER BY daily_revenue DESC;",'t',
    ['Group rooms by room_type in CTE.','Compute total rooms, occupied count, and realized revenue.'],'Monitors inpatient revenue yield by accommodation category.',40,8),

  q('hc-L5-043','healthcare',5,43,'core','Physician Practice Diversity: Consultations, Prescriptions & Inpatient (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Full practice clinical profile: Using a 3-stage CTE, count completed appointments, prescriptions authorized, and inpatient admissions managed per doctor. Return doctor name, specialty, completed visits, prescriptions, and inpatient admissions.',
    'WITH appts AS (...), rxs AS (...), adms AS (...) SELECT name, specialty, visits, rxs, adms.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY'],['name','specialty','completed_visits','prescriptions_count','admissions_count'],
    "WITH appts AS (SELECT doctor_id, COUNT(id) AS completed_visits FROM appointments WHERE status = 'completed' GROUP BY doctor_id), rxs AS (SELECT doctor_id, COUNT(id) AS prescriptions_count FROM prescriptions GROUP BY doctor_id), adms AS (SELECT admitting_doctor_id, COUNT(id) AS admissions_count FROM inpatient_admissions GROUP BY admitting_doctor_id) SELECT d.name, d.specialty, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(r.prescriptions_count, 0) AS prescriptions_count, COALESCE(ad.admissions_count, 0) AS admissions_count FROM doctors d LEFT JOIN appts a ON d.id = a.doctor_id LEFT JOIN rxs r ON d.id = r.doctor_id LEFT JOIN adms ad ON d.id = ad.admitting_doctor_id ORDER BY completed_visits DESC, admissions_count DESC LIMIT 24;",'t',
    ['Aggregate encounters across 3 CTEs (outpatient visits, prescriptions, inpatient admissions).','Join to doctors table.','Order by completed_visits DESC LIMIT 24.'],'Holistic 360-degree physician practice profile integrating outpatient, inpatient, and pharmacy activity.',40,11),

  q('hc-L5-044','healthcare',5,44,'core','Health Plan Inpatient Financial Liability Exposure (CTE)','Jordan Chen','Director of Billing',
    'Carrier inpatient risk: Using a CTE that joins inpatient admissions to rooms, patients, and billing, calculate total billed charges, insurance covered, and patient balance owed by insurance provider. Return insurance provider, total billed, insurance covered, and patient balance.',
    'WITH payer_inpatient AS (...) SELECT insurance_provider, total_billed, insurance_covered, patient_balance.',['WITH CTE','INNER JOIN','GROUP BY','SUM'],['insurance_provider','total_billed','insurance_covered','patient_balance'],
    "WITH payer_inpatient AS (SELECT p.insurance_provider, ROUND(SUM(b.total_charge), 2) AS total_billed, ROUND(SUM(b.insurance_covered), 2) AS total_insurance_covered, ROUND(SUM(b.patient_balance), 2) AS total_patient_balance FROM billing b JOIN patients p ON b.patient_id = p.id GROUP BY p.insurance_provider) SELECT insurance_provider, total_billed, total_insurance_covered, total_patient_balance FROM payer_inpatient ORDER BY total_billed DESC;",'t',
    ['Join billing to patients in CTE.','Sum total_charge, insurance_covered, and patient_balance per provider.'],'Profiles financial exposure across commercial and government health plans.',40,8),

  q('hc-L5-045','healthcare',5,45,'core','Emergency and High-Severity Outpatient Consultations by Department (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Acuity surge review: Using a CTE, count Urgent appointments and high-fee consultations (fee > $200) for each clinical department. Return department name, urgent appointments, and high-fee encounters count.',
    'WITH urgent_stats AS (...) SELECT department_name, urgent_count, high_fee_count.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['department_name','urgent_count','high_fee_count'],
    "WITH urgent_stats AS (SELECT dept.name AS department_name, SUM(CASE WHEN a.appointment_type = 'Urgent' THEN 1 ELSE 0 END) AS urgent_count, SUM(CASE WHEN a.fee > 200.00 THEN 1 ELSE 0 END) AS high_fee_count FROM departments dept JOIN doctors doc ON dept.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id GROUP BY dept.id, dept.name) SELECT department_name, urgent_count, high_fee_count FROM urgent_stats ORDER BY urgent_count DESC, high_fee_count DESC;",'t',
    ['Join departments to doctors to appointments in CTE.','Compute urgent count and high-fee count.'],'Identifies acute care demand distribution across hospital service lines.',40,8),

  q('hc-L5-046','healthcare',5,46,'core','Diabetic vs Hypertensive Patient Incurred Charge Comparison (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Chronic disease economics: Using a 2-stage CTE, calculate total patients, total hospital billing, and average charge per patient for Type 2 Diabetes (E11.9) vs Essential Hypertension (I10). Return ICD-10 code, description, patient count, and average charge.',
    'WITH diag_pts AS (...), diag_spend AS (...) SELECT icd10_code, description, patient_count, avg_charge.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','AVG'],['icd10_code','description','patient_count','avg_charge'],
    "WITH diag_billing AS (SELECT dg.icd10_code, dg.description, dg.patient_id, b.total_charge FROM diagnoses dg JOIN billing b ON dg.appointment_id = b.appointment_id WHERE dg.icd10_code IN ('E11.9', 'I10')) SELECT icd10_code, description, COUNT(DISTINCT patient_id) AS patient_count, ROUND(AVG(total_charge), 2) AS avg_charge FROM diag_billing GROUP BY icd10_code, description ORDER BY avg_charge DESC;",'t',
    ['Filter diagnoses for diabetes and hypertension joined to billing in CTE.','Compute distinct patient count and average charge.'],'Compares disease-specific healthcare expenditure for dominant chronic conditions.',40,9),

  q('hc-L5-047','healthcare',5,47,'core','Hospital Inpatient Readmission Rate by Admitting Doctor (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Physician readmission index: Using a CTE with LAG(), count total admissions and readmissions occurring within 30 days for each admitting doctor. Return doctor name, specialty, total admissions, and readmission count.',
    'WITH readms AS (...) SELECT name, specialty, total_admissions, readmission_count.',['WITH CTE','LAG','PARTITION BY','INNER JOIN','GROUP BY','SUM CASE'],['name','specialty','total_admissions','readmission_count'],
    "WITH readms AS (SELECT admitting_doctor_id, id, admission_date, (admission_date - LAG(discharge_date, 1) OVER (PARTITION BY patient_id ORDER BY admission_date ASC)) AS days_between FROM inpatient_admissions) SELECT d.name, d.specialty, COUNT(r.id) AS total_admissions, SUM(CASE WHEN r.days_between IS NOT NULL AND r.days_between <= 30 THEN 1 ELSE 0 END) AS readmission_count FROM doctors d JOIN readms r ON d.id = r.admitting_doctor_id GROUP BY d.id, d.name, d.specialty ORDER BY readmission_count DESC, total_admissions DESC;",'t',
    ['Compute readmission interval with LAG() in CTE.','Aggregate admissions and 30-day readmissions per admitting physician.'],'Evaluates clinical physician performance against quality readmission metrics.',40,10),

  q('hc-L5-048','healthcare',5,48,'core','Top Cost Medication Prescriptions by Specialty (ROW_NUMBER CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Specialty pharmacotherapy expense ceiling: Using a CTE with ROW_NUMBER, find the single highest unit-cost medication prescribed by each doctor specialty. Return specialty, medication name, and unit cost.',
    'WITH ranked_meds AS (...) SELECT specialty, medication_name, unit_cost WHERE rn = 1.',['WITH CTE','ROW_NUMBER','PARTITION BY','INNER JOIN'],['specialty','medication_name','unit_cost'],
    "WITH ranked_meds AS (SELECT d.specialty, pr.medication_name, m.unit_cost, ROW_NUMBER() OVER (PARTITION BY d.specialty ORDER BY m.unit_cost DESC, pr.medication_name ASC) AS rn FROM prescriptions pr JOIN doctors d ON pr.doctor_id = d.id JOIN medications m ON pr.medication_name = m.name) SELECT specialty, medication_name, unit_cost FROM ranked_meds WHERE rn = 1 ORDER BY unit_cost DESC, specialty;",'t',
    ['Join prescriptions to doctors and medications in CTE.','Rank by unit_cost DESC partitioned by specialty.','Filter rn = 1.'],'Surfaces the peak-cost therapeutic agent authorized in each medical discipline.',40,9),

  q('hc-L5-049','healthcare',5,49,'core','Hospital Outpatient Visit Adherence by Day of Week (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Operational clinic flow: Using a CTE, calculate completed visits and no-show appointments for each day of the week (using EXTRACT DOW). Return day of week number, completed count, and no-show count.',
    'WITH dow_stats AS (...) SELECT day_of_week, completed_count, no_show_count.',['WITH CTE','GROUP BY','SUM CASE','EXTRACT'],['day_of_week','completed_count','no_show_count'],
    "WITH dow_stats AS (SELECT EXTRACT(DOW FROM appointment_date) AS day_of_week, SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) AS completed_count, SUM(CASE WHEN status = 'no_show' THEN 1 ELSE 0 END) AS no_show_count FROM appointments GROUP BY EXTRACT(DOW FROM appointment_date)) SELECT day_of_week, completed_count, no_show_count FROM dow_stats ORDER BY day_of_week ASC;",'t',
    ['Extract DOW from appointment_date in CTE.','Aggregate completed and no-show counts by day of week.'],'Optimizes outpatient clinic scheduling and front-desk staffing across the weekly calendar.',40,8),

  q('hc-L5-050','healthcare',5,50,'core','Integrated Payer Financial Health and Claim Velocity (Multi-Stage CTE)','Jordan Chen','Director of Billing',
    'Payer master intelligence: Using a 2-stage CTE, calculate gross claims, approved claims, total approved dollars, and average settlement days for each insurance provider. Return insurance provider, total claims, approved claims, approved dollars, and avg settlement days.',
    'WITH payer_claims AS (...) SELECT insurance_provider, total_claims, approved_claims, total_approved, avg_settlement_days.',['WITH CTE','GROUP BY','SUM','AVG'],['insurance_provider','total_claims','approved_claims','total_approved','avg_settlement_days'],
    "WITH payer_claims AS (SELECT insurance_provider, COUNT(id) AS total_claims, SUM(CASE WHEN status = 'approved' THEN 1 ELSE 0 END) AS approved_claims, ROUND(SUM(approved_amount), 2) AS total_approved, ROUND(AVG(settlement_days), 1) AS avg_settlement_days FROM insurance_claims GROUP BY insurance_provider) SELECT insurance_provider, total_claims, approved_claims, total_approved, avg_settlement_days FROM payer_claims ORDER BY total_approved DESC;",'t',
    ['Aggregate claim metrics per insurance provider in CTE.','Select carrier financial and velocity KPIs.'],'Executive health plan review benchmarking contractual yield and settlement turnaround.',40,9),

  // 51–75: Advanced (Multi-Table Hospital P&L, Executive Yield Dashboards, Longitudinal Care Cohorts)
  q('hc-L5-051','healthcare',5,51,'advanced','Hospital Consolidated Department Revenue Model (Multi-Stage CTE)','Jordan Chen','Director of Billing',
    'Service line consolidated revenue: Construct a multi-stage CTE combining outpatient appointment fees, inpatient room daily rates for occupied rooms, and standard medical procedure costs per department. Return department name, appointment revenue, room revenue, and procedure revenue.',
    'WITH appt_rev AS (...), room_rev AS (...), proc_rev AS (...) SELECT department_name, appt_rev, room_rev, proc_rev.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','SUM'],['department_name','appt_revenue','room_revenue','proc_revenue'],
    "WITH appt_rev AS (SELECT dept.id AS department_id, dept.name AS department_name, ROUND(SUM(a.fee), 2) AS appt_revenue FROM departments dept JOIN doctors doc ON dept.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id WHERE a.status = 'completed' GROUP BY dept.id, dept.name), room_rev AS (SELECT department_id, ROUND(SUM(daily_rate), 2) AS room_revenue FROM rooms WHERE is_occupied = TRUE GROUP BY department_id), proc_rev AS (SELECT department_id, ROUND(SUM(standard_cost), 2) AS proc_revenue FROM medical_procedures GROUP BY department_id) SELECT a.department_name, COALESCE(a.appt_revenue, 0.00) AS appt_revenue, COALESCE(r.room_revenue, 0.00) AS room_revenue, COALESCE(p.proc_revenue, 0.00) AS proc_revenue FROM appt_rev a LEFT JOIN room_rev r ON a.department_id = r.department_id LEFT JOIN proc_rev p ON a.department_id = p.department_id ORDER BY a.appt_revenue DESC;",'t',
    ['Aggregate revenue streams in 3 separate CTEs (outpatient, inpatient beds, procedures).','Join on department_id with COALESCE.','Order by appt_revenue DESC.'],'Enterprise consolidated revenue breakdown uniting ambulatory, bed, and surgical income streams.',45,12),

  q('hc-L5-052','healthcare',5,52,'advanced','Physician Productivity vs Prescription Volume Matrix (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Physician efficiency matrix: Using a CTE, calculate completed consultations, total visit fees, and prescriptions written for each doctor. Categorize doctors into: High Productivity (fees >= $1000), Moderate ($500-$999), Low (< $500). Return doctor name, specialty, completed visits, total fees, and productivity tier.',
    'WITH doc_matrix AS (...) SELECT name, specialty, visits, total_fees, productivity_tier.',['WITH CTE','INNER JOIN','GROUP BY','CASE WHEN'],['name','specialty','completed_visits','total_fees','productivity_tier'],
    "WITH doc_matrix AS (SELECT d.name, d.specialty, COUNT(a.id) AS completed_visits, ROUND(SUM(a.fee), 2) AS total_fees FROM doctors d JOIN appointments a ON d.id = a.doctor_id WHERE a.status = 'completed' GROUP BY d.id, d.name, d.specialty) SELECT name, specialty, completed_visits, total_fees, CASE WHEN total_fees >= 1000.00 THEN 'High Productivity' WHEN total_fees BETWEEN 500.00 AND 999.99 THEN 'Moderate' ELSE 'Low' END AS productivity_tier FROM doc_matrix ORDER BY total_fees DESC;",'t',
    ['Compute completed visits and total fees in CTE.','Classify into productivity tiers using CASE in outer query.'],'Segments medical staff into clinical productivity cohorts for leadership reviews.',45,10),

  q('hc-L5-053','healthcare',5,53,'advanced','Hospital Inpatient Bed Occupancy and Staffing Balance (Multi-Stage CTE)','Marcus Thorne','Chief Nursing Officer',
    'Campus acuity staffing index: Using a 2-stage CTE, calculate total beds, occupied beds, and Day shift nurses per department. Calculate the occupied-beds-per-day-nurse ratio. Return department name, occupied beds, Day nurses, and bed-to-nurse ratio.',
    'WITH bed_stats AS (...), nurse_stats AS (...) SELECT department_name, occupied_beds, day_nurses, ratio.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','ARITHMETIC'],['department_name','occupied_beds','day_nurses','beds_per_day_nurse'],
    "WITH bed_stats AS (SELECT d.id AS department_id, d.name AS department_name, SUM(CASE WHEN r.is_occupied THEN 1 ELSE 0 END) AS occupied_beds FROM departments d LEFT JOIN rooms r ON d.id = r.department_id GROUP BY d.id, d.name), nurse_stats AS (SELECT department_id, SUM(CASE WHEN shift = 'Day' THEN 1 ELSE 0 END) AS day_nurses FROM nurses GROUP BY department_id) SELECT b.department_name, b.occupied_beds, n.day_nurses, ROUND(b.occupied_beds::NUMERIC / NULLIF(n.day_nurses, 0), 2) AS beds_per_day_nurse FROM bed_stats b JOIN nurse_stats n ON b.department_id = n.department_id ORDER BY beds_per_day_nurse DESC;",'t',
    ['Compute occupied beds and day nurses in dual CTEs.','Calculate beds_per_day_nurse ratio.'],'Evaluates critical nurse-to-patient staffing safety thresholds.',45,10),

  q('hc-L5-054','healthcare',5,54,'advanced','Payer Bad Debt & Overdue Balance Aging Risk (CTE)','Jordan Chen','Director of Billing',
    'Health plan risk profiling: Using a CTE, calculate total overdue vouchers, overdue patient balance sum, and average overdue balance for each insurance carrier. Return insurance provider, overdue count, total overdue balance, and average balance.',
    'WITH overdue_stats AS (...) SELECT insurance_provider, overdue_count, total_overdue_balance, avg_overdue_balance.',['WITH CTE','INNER JOIN','GROUP BY','SUM','AVG'],['insurance_provider','overdue_count','total_overdue_balance','avg_overdue_balance'],
    "WITH overdue_stats AS (SELECT p.insurance_provider, COUNT(b.id) AS overdue_count, ROUND(SUM(b.patient_balance), 2) AS total_overdue_balance, ROUND(AVG(b.patient_balance), 2) AS avg_overdue_balance FROM billing b JOIN patients p ON b.patient_id = p.id WHERE b.status = 'overdue' GROUP BY p.insurance_provider) SELECT insurance_provider, overdue_count, total_overdue_balance, avg_overdue_balance FROM overdue_stats ORDER BY total_overdue_balance DESC;",'t',
    ['Join overdue billing records to patients in CTE.','Sum and average patient_balance per insurance provider.'],'Evaluates bad-debt write-off risks across commercial and public health plans.',45,9),

  q('hc-L5-055','healthcare',5,55,'advanced','High Acuity Patient Clinical Touchpoint Summary (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Severe patient clinical audit: Using a 3-stage CTE, identify patients diagnosed with Severe conditions, and calculate their completed appointments count and total laboratory tests performed. Return patient first name, last name, severe diagnoses count, completed visits, and lab tests count.',
    'WITH sev_pts AS (...), appt_counts AS (...), lab_counts AS (...) SELECT first_name, last_name, severe_count, visits, labs.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','LEFT JOIN','GROUP BY'],['first_name','last_name','severe_diagnoses_count','completed_visits','lab_tests_count'],
    "WITH sev_pts AS (SELECT patient_id, COUNT(id) AS severe_count FROM diagnoses WHERE severity = 'Severe' GROUP BY patient_id), appt_counts AS (SELECT patient_id, COUNT(id) AS completed_visits FROM appointments WHERE status = 'completed' GROUP BY patient_id), lab_counts AS (SELECT patient_id, COUNT(id) AS lab_tests_count FROM patient_lab_results GROUP BY patient_id) SELECT p.first_name, p.last_name, s.severe_count AS severe_diagnoses_count, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(l.lab_tests_count, 0) AS lab_tests_count FROM patients p JOIN sev_pts s ON p.id = s.patient_id LEFT JOIN appt_counts a ON p.id = a.patient_id LEFT JOIN lab_counts l ON p.id = l.patient_id ORDER BY s.severe_count DESC, completed_visits DESC;",'t',
    ['Filter patients with Severe diagnoses in sev_pts CTE.','Join with outpatient visits and lab test counts.','Order by severe diagnoses count DESC.'],'Surfaces clinical utilization intensity for high-acuity patient cohorts.',45,11),

  q('hc-L5-056','healthcare',5,56,'advanced','Physician Outpatient Visit Revenue Quartiles within Specialty (CTE)','Jordan Chen','Director of Billing',
    'Intra-specialty fee benchmarking: Using a CTE, calculate gross completed visit revenue per doctor, then apply NTILE(4) partitioned by specialty to assign doctors to quartile tiers. Return specialty, doctor name, gross revenue, and revenue quartile.',
    'WITH doc_rev AS (...) SELECT specialty, name, gross_revenue, NTILE(4) OVER (PARTITION BY specialty ORDER BY gross_revenue DESC).',['WITH CTE','NTILE','PARTITION BY','INNER JOIN','GROUP BY'],['specialty','name','gross_revenue','revenue_quartile'],
    "WITH doc_rev AS (SELECT d.specialty, d.name, ROUND(SUM(a.fee), 2) AS gross_revenue FROM doctors d JOIN appointments a ON d.id = a.doctor_id WHERE a.status = 'completed' GROUP BY d.id, d.specialty, d.name) SELECT specialty, name, gross_revenue, NTILE(4) OVER (PARTITION BY specialty ORDER BY gross_revenue DESC) AS revenue_quartile FROM doc_rev ORDER BY specialty, revenue_quartile, gross_revenue DESC;",'t',
    ['Compute revenue per doctor in CTE.','Apply NTILE(4) partitioned by specialty in outer query.'],'Compares clinician financial production relative to peers within the same clinical specialty.',45,10),

  q('hc-L5-057','healthcare',5,57,'advanced','Operating Room Duration and Procedure Cost Efficiency (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Surgical cost-per-minute index: Using a CTE, calculate cost-per-minute (standard_cost / duration_minutes) for each medical procedure, joined with department name. Return code, procedure name, department name, duration minutes, standard cost, and cost per minute.',
    'WITH proc_eff AS (...) SELECT code, procedure_name, department_name, duration_minutes, standard_cost, cost_per_minute.',['WITH CTE','INNER JOIN','ARITHMETIC','ROUND'],['code','procedure_name','department_name','duration_minutes','standard_cost','cost_per_minute'],
    "WITH proc_eff AS (SELECT p.code, p.procedure_name, d.name AS department_name, p.duration_minutes, p.standard_cost, ROUND(p.standard_cost / NULLIF(p.duration_minutes, 0), 2) AS cost_per_minute FROM medical_procedures p JOIN departments d ON p.department_id = d.id) SELECT code, procedure_name, department_name, duration_minutes, standard_cost, cost_per_minute FROM proc_eff ORDER BY cost_per_minute DESC;",'t',
    ['Compute cost_per_minute in CTE.','Order by cost_per_minute DESC.'],'Measures procedural revenue yield per minute of operating room time.',45,9),

  q('hc-L5-058','healthcare',5,58,'advanced','Inpatient 30-Day Readmission Clinical Cost Impact (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Readmission financial burden: Using a multi-stage CTE, identify inpatient readmissions within 30 days, join to billing to aggregate the total billed charges incurred by readmitted patients. Return patient_id, readmission count, and total charges billed.',
    'WITH readms AS (...), pt_bills AS (...) SELECT patient_id, readmissions_count, total_billed.',['WITH CTE','MULTI-STAGE CTE','LAG','PARTITION BY','INNER JOIN','GROUP BY','SUM'],['patient_id','readmissions_count','total_billed'],
    "WITH readms AS (SELECT patient_id, id, admission_date, (admission_date - LAG(discharge_date, 1) OVER (PARTITION BY patient_id ORDER BY admission_date ASC)) AS days_between FROM inpatient_admissions), readm_pts AS (SELECT patient_id, COUNT(id) AS readmissions_count FROM readms WHERE days_between IS NOT NULL AND days_between <= 30 GROUP BY patient_id), pt_bills AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_billed FROM billing GROUP BY patient_id) SELECT r.patient_id, r.readmissions_count, b.total_billed FROM readm_pts r JOIN pt_bills b ON r.patient_id = b.patient_id ORDER BY b.total_billed DESC;",'t',
    ['Identify 30-day readmissions with LAG in readms CTE.','Aggregate hospital billing for readmitted patients in pt_bills CTE.','Order by total_billed DESC.'],'Quantifies financial charges tied to hospital readmission penalty cases.',45,11),

  q('hc-L5-059','healthcare',5,59,'advanced','Diagnostic Laboratory Yield and Abnormal Flag Concentration (CTE)','Dr. Anthony Clark','Director of Pathology & Lab',
    'Diagnostic abnormality index: Using a CTE, calculate total tests performed, High flags count, Low flags count, and total abnormal percentage for each lab test. Return test name, category, total tests, High count, Low count, and abnormal pct.',
    'WITH lab_yield AS (...) SELECT test_name, category, total_tests, high_flags, low_flags, abnormal_pct.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['test_name','category','total_tests','high_flags','low_flags','abnormal_pct'],
    "WITH lab_yield AS (SELECT lt.test_name, lt.category, COUNT(plr.id) AS total_tests, SUM(CASE WHEN plr.flag = 'HIGH' THEN 1 ELSE 0 END) AS high_flags, SUM(CASE WHEN plr.flag = 'LOW' THEN 1 ELSE 0 END) AS low_flags FROM lab_tests lt LEFT JOIN patient_lab_results plr ON lt.id = plr.test_id GROUP BY lt.id, lt.test_name, lt.category) SELECT test_name, category, total_tests, high_flags, low_flags, ROUND((high_flags + low_flags)::NUMERIC / NULLIF(total_tests, 0) * 100.0, 1) AS abnormal_pct FROM lab_yield ORDER BY abnormal_pct DESC;",'t',
    ['Compute high and low flags per lab test in CTE.','Calculate combined abnormal percentage in outer query.'],'Pinpoints diagnostic tests with the highest clinical abnormality detection rate.',45,9),

  q('hc-L5-060','healthcare',5,60,'advanced','Hospital Formulary Spend Contribution by Clinical Specialty (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Specialty medication expenditure: Using a multi-stage CTE, calculate total prescriptions authored and total estimated medication cost (prescriptions * unit_cost) for each medical specialty. Return specialty, prescriptions count, and total spend.',
    'WITH spec_rx AS (...) SELECT specialty, rx_count, total_formulary_spend.',['WITH CTE','INNER JOIN','GROUP BY','SUM','ARITHMETIC'],['specialty','rx_count','total_formulary_spend'],
    "WITH spec_rx AS (SELECT d.specialty, COUNT(pr.id) AS rx_count, ROUND(SUM(m.unit_cost), 2) AS total_formulary_spend FROM prescriptions pr JOIN doctors d ON pr.doctor_id = d.id JOIN medications m ON pr.medication_name = m.name GROUP BY d.specialty) SELECT specialty, rx_count, total_formulary_spend FROM spec_rx ORDER BY total_formulary_spend DESC;",'t',
    ['Join prescriptions to doctors and medications in CTE.','Sum unit_cost per specialty.'],'Evaluates specialty-level pharmacotherapy budget utilization.',45,9),

  q('hc-L5-061','healthcare',5,61,'advanced','Hospital Inpatient Accommodation Yield vs Capacity Floor (Multi-Stage CTE)','Marcus Thorne','Chief Nursing Officer',
    'Department capacity economics: Using a 2-stage CTE, compute total potential daily room revenue (all rooms * rate) and actual realized daily room revenue (occupied rooms * rate) per department. In Stage 2, compute the revenue realization percentage. Return department name, potential revenue, realized revenue, and realization pct.',
    'WITH dept_rooms AS (...) SELECT department_name, potential_revenue, realized_revenue, realization_pct.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['department_name','potential_revenue','realized_revenue','realization_pct'],
    "WITH dept_rooms AS (SELECT d.name AS department_name, ROUND(SUM(r.daily_rate), 2) AS potential_revenue, ROUND(SUM(CASE WHEN r.is_occupied THEN r.daily_rate ELSE 0 END), 2) AS realized_revenue FROM departments d JOIN rooms r ON d.id = r.department_id GROUP BY d.id, d.name) SELECT department_name, potential_revenue, realized_revenue, ROUND(realized_revenue / NULLIF(potential_revenue, 0) * 100.0, 1) AS realization_pct FROM dept_rooms ORDER BY realized_revenue DESC;",'t',
    ['Compute potential and realized daily revenue in CTE.','Calculate realization percentage.'],'Evaluates departmental bed accommodation monetization efficiency.',45,9),

  q('hc-L5-062','healthcare',5,62,'advanced','Chronic Comorbidity Patient Incurred Billing Exposure (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Multimorbid financial burden: Using a CTE, identify patients diagnosed with at least 2 distinct conditions, and join to billing to compute their total billed charges. Return patient first name, last name, distinct diagnoses count, and total billed charges.',
    'WITH multi_diag AS (...) SELECT p.first_name, p.last_name, m.diag_count, SUM(b.total_charge).',['WITH CTE','INNER JOIN','GROUP BY','HAVING','COUNT DISTINCT'],['first_name','last_name','diagnoses_count','total_hospital_billed'],
    "WITH multi_diag AS (SELECT patient_id, COUNT(DISTINCT icd10_code) AS diag_count FROM diagnoses GROUP BY patient_id HAVING COUNT(DISTINCT icd10_code) >= 2) SELECT p.first_name, p.last_name, m.diag_count AS diagnoses_count, ROUND(SUM(b.total_charge), 2) AS total_hospital_billed FROM multi_diag m JOIN patients p ON m.patient_id = p.id JOIN billing b ON p.id = b.patient_id GROUP BY p.id, p.first_name, p.last_name, m.diag_count ORDER BY total_hospital_billed DESC;",'t',
    ['Filter patients with >= 2 distinct diagnoses in multi_diag CTE.','Join to patients and billing to aggregate total hospital charges.'],'Quantifies financial charges for chronic multimorbid patient cohorts.',45,10),

  q('hc-L5-063','healthcare',5,63,'advanced','Clinical Laboratory Pricing Spread and Standard Deviation Proxy (CTE)','Dr. Anthony Clark','Director of Pathology & Lab',
    'Pathology pricing dispersion: Using a CTE, calculate standard fee variance (max_fee - min_fee) and average standard fee across diagnostic categories. Return category, test count, min fee, max fee, fee spread, and average fee.',
    'WITH cat_pricing AS (...) SELECT category, test_count, min_fee, max_fee, fee_spread, avg_fee.',['WITH CTE','GROUP BY','MIN','MAX','AVG'],['category','test_count','min_fee','max_fee','fee_spread','avg_fee'],
    "WITH cat_pricing AS (SELECT category, COUNT(id) AS test_count, ROUND(MIN(standard_fee), 2) AS min_fee, ROUND(MAX(standard_fee), 2) AS max_fee, ROUND(MAX(standard_fee) - MIN(standard_fee), 2) AS fee_spread, ROUND(AVG(standard_fee), 2) AS avg_fee FROM lab_tests GROUP BY category) SELECT category, test_count, min_fee, max_fee, fee_spread, avg_fee FROM cat_pricing ORDER BY fee_spread DESC;",'t',
    ['Compute min, max, spread, and avg fee per category in CTE.','Order by fee_spread DESC.'],'Analyzes price variance across pathology diagnostic disciplines.',45,8),

  q('hc-L5-064','healthcare',5,64,'advanced','Physician Scheduling Utilization and Patient Adherence (CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Clinical schedule yield: Using a CTE, calculate total scheduled visits, completed encounters, cancelled encounters, and no-show encounters for each doctor specialty. Return specialty, total scheduled, completed, cancelled, and no-shows.',
    'WITH spec_sched AS (...) SELECT specialty, total_scheduled, completed, cancelled, no_shows.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['specialty','total_scheduled','completed','cancelled','no_shows'],
    "WITH spec_sched AS (SELECT d.specialty, COUNT(a.id) AS total_scheduled, SUM(CASE WHEN a.status = 'completed' THEN 1 ELSE 0 END) AS completed, SUM(CASE WHEN a.status = 'cancelled' THEN 1 ELSE 0 END) AS cancelled, SUM(CASE WHEN a.status = 'no_show' THEN 1 ELSE 0 END) AS no_shows FROM doctors d JOIN appointments a ON d.id = a.doctor_id GROUP BY d.specialty) SELECT specialty, total_scheduled, completed, cancelled, no_shows FROM spec_sched ORDER BY total_scheduled DESC;",'t',
    ['Join doctors to appointments in CTE.','Pivot schedule status counts per specialty.'],'Evaluates outpatient clinic operational throughput and cancellation friction.',45,9),

  q('hc-L5-065','healthcare',5,65,'advanced','Payer Contractual Realization Index by Commercial Health Plan (CTE)','Jordan Chen','Director of Billing',
    'Commercial payer scorecard: Using a CTE that filters for major commercial payers (BlueCross, Aetna, UnitedHealth, Cigna), calculate claim count, total claim amount, approved amount, and realization percentage. Return insurance provider, claims count, gross claimed, net approved, and realization pct.',
    'WITH comm_payers AS (...) SELECT insurance_provider, claims_count, gross_claimed, net_approved, realization_pct.',['WITH CTE','WHERE','GROUP BY','SUM','ROUND'],['insurance_provider','claims_count','gross_claimed','net_approved','realization_pct'],
    "WITH comm_payers AS (SELECT insurance_provider, COUNT(id) AS claims_count, ROUND(SUM(claim_amount), 2) AS gross_claimed, ROUND(SUM(approved_amount), 2) AS net_approved FROM insurance_claims WHERE insurance_provider IN ('BlueCross', 'Aetna', 'UnitedHealth', 'Cigna') GROUP BY insurance_provider) SELECT insurance_provider, claims_count, gross_claimed, net_approved, ROUND(net_approved / NULLIF(gross_claimed, 0) * 100.0, 1) AS realization_pct FROM comm_payers ORDER BY realization_pct DESC;",'t',
    ['Filter commercial payers in CTE and aggregate claim totals.','Calculate net contractual realization percentage.'],'Benchmarks commercial payer contract recovery efficiency.',45,9),

  q('hc-L5-066','healthcare',5,66,'advanced','Inpatient Length of Stay vs Daily Accommodation Charges (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Inpatient financial intensity: Using a CTE that joins inpatient admissions to rooms, calculate total inpatient days and total accommodation charges (days * daily_rate) for each completed admission. Return admission id, patient_id, length of stay, daily rate, and total room charges.',
    'WITH stay_charges AS (...) SELECT id, patient_id, length_of_stay, daily_rate, total_room_charges.',['WITH CTE','INNER JOIN','WHERE','ARITHMETIC'],['id','patient_id','length_of_stay','daily_rate','total_room_charges'],
    "WITH stay_charges AS (SELECT ia.id, ia.patient_id, (ia.discharge_date - ia.admission_date) AS length_of_stay, r.daily_rate, ROUND((ia.discharge_date - ia.admission_date) * r.daily_rate, 2) AS total_room_charges FROM inpatient_admissions ia JOIN rooms r ON ia.room_id = r.id WHERE ia.discharge_date IS NOT NULL) SELECT id, patient_id, length_of_stay, daily_rate, total_room_charges FROM stay_charges ORDER BY total_room_charges DESC;",'t',
    ['Compute stay and room charges as days * daily_rate in CTE.','Order by total_room_charges DESC.'],'Calculates inpatient room and board charge generation per hospitalization.',45,9),

  q('hc-L5-067','healthcare',5,67,'advanced','Diagnostic Biopsy and Procedure Durations Across Clinical Towers (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Facility procedural block allocation: Using a CTE that joins medical procedures to departments, calculate average procedure duration and total procedural standard cost per building tower. Return building, procedure count, avg duration minutes, and total cost.',
    'WITH bldg_procs AS (...) SELECT building, procedure_count, avg_duration_minutes, total_cost.',['WITH CTE','INNER JOIN','GROUP BY','AVG','SUM'],['building','procedure_count','avg_duration_minutes','total_cost'],
    "WITH bldg_procs AS (SELECT d.building, COUNT(p.id) AS procedure_count, ROUND(AVG(p.duration_minutes), 1) AS avg_duration_minutes, ROUND(SUM(p.standard_cost), 2) AS total_cost FROM departments d JOIN medical_procedures p ON d.id = p.department_id GROUP BY d.building) SELECT building, procedure_count, avg_duration_minutes, total_cost FROM bldg_procs ORDER BY total_cost DESC;",'t',
    ['Join departments to procedures in CTE.','Compute procedure count, avg duration, and total cost per building.'],'Models surgical block time and procedural revenue potential across hospital towers.',45,9),

  q('hc-L5-068','healthcare',5,68,'advanced','Senior Patient Polypharmacy and Diagnostic Risk Profile (Multi-Stage CTE)','Dr. Evelyn Reed','Chief Medical Officer',
    'Geriatric polypharmacy audit: Using a multi-stage CTE, identify senior patients (born before 1965), and calculate their distinct medications prescribed count and distinct diagnoses count. Return patient first name, last name, date of birth, prescriptions count, and diagnoses count.',
    'WITH sr_pts AS (...), rx_counts AS (...), diag_counts AS (...) SELECT first_name, last_name, dob, rxs, diags.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','COUNT DISTINCT'],['first_name','last_name','dob','prescriptions_count','diagnoses_count'],
    "WITH sr_pts AS (SELECT id, first_name, last_name, dob FROM patients WHERE dob < '1965-01-01'), rx_counts AS (SELECT patient_id, COUNT(id) AS rx_cnt FROM prescriptions GROUP BY patient_id), diag_counts AS (SELECT patient_id, COUNT(id) AS diag_cnt FROM diagnoses GROUP BY patient_id) SELECT s.first_name, s.last_name, s.dob, COALESCE(r.rx_cnt, 0) AS prescriptions_count, COALESCE(d.diag_cnt, 0) AS diagnoses_count FROM sr_pts s LEFT JOIN rx_counts r ON s.id = r.patient_id LEFT JOIN diag_counts d ON s.id = d.patient_id ORDER BY prescriptions_count DESC, diagnoses_count DESC;",'t',
    ['Filter senior patients in sr_pts CTE.','Join with prescription and diagnosis counts.','Order by prescriptions count DESC.'],'Surfaces vulnerable geriatric patients managing complex polypharmacy regimens.',45,11),

  q('hc-L5-069','healthcare',5,69,'advanced','Hospital Billing Cash Recovery Efficiency Ratio (CTE)','Jordan Chen','Director of Billing',
    'Cash conversion efficiency: Using a CTE, calculate total billed charges, total copays collected, total insurance covered, and total uncollected patient balance across all hospital billing records. Return total billed, total copays, insurance covered, and uncollected balance.',
    'WITH ar_totals AS (...) SELECT total_billed, total_copays, total_insurance_covered, total_patient_balance.',['WITH CTE','SUM'],['total_billed','total_copays','total_insurance_covered','total_patient_balance'],
    "WITH ar_totals AS (SELECT ROUND(SUM(total_charge), 2) AS total_billed, ROUND(SUM(copay_amount), 2) AS total_copays, ROUND(SUM(insurance_covered), 2) AS total_insurance_covered, ROUND(SUM(patient_balance), 2) AS total_patient_balance FROM billing) SELECT total_billed, total_copays, total_insurance_covered, total_patient_balance FROM ar_totals;",'f',
    ['Compute grand totals for charges, copays, insurance covered, and patient balance in CTE.','Select financial summary.'],'Executive hospital billing reconciliation balancing collected cash against uncollected receivables.',45,8),

  q('hc-L5-070','healthcare',5,70,'advanced','Physician Outpatient Clinical Revenue Decile Distribution (NTILE CTE)','Jordan Chen','Director of Billing',
    'Medical staff production deciles: Using a CTE, compute gross completed appointment revenue for each doctor, then apply NTILE(10) to assign doctors to performance deciles. Return doctor name, specialty, gross revenue, and production decile.',
    'WITH doc_rev AS (...) SELECT name, specialty, gross_revenue, NTILE(10) OVER (ORDER BY gross_revenue DESC).',['WITH CTE','NTILE','INNER JOIN','GROUP BY'],['name','specialty','gross_revenue','production_decile'],
    "WITH doc_rev AS (SELECT d.name, d.specialty, ROUND(SUM(a.fee), 2) AS gross_revenue FROM doctors d JOIN appointments a ON d.id = a.doctor_id WHERE a.status = 'completed' GROUP BY d.id, d.name, d.specialty) SELECT name, specialty, gross_revenue, NTILE(10) OVER (ORDER BY gross_revenue DESC) AS production_decile FROM doc_rev ORDER BY production_decile, gross_revenue DESC;",'t',
    ['Compute revenue per doctor in CTE.','Apply NTILE(10) OVER (ORDER BY gross_revenue DESC) in outer query.'],'Segments physicians into ten granular production deciles for medical executive committee reviews.',45,10),

  q('hc-L5-071','healthcare',5,71,'advanced','Nursing Workforce Certification and Shift Distribution (CTE)','Marcus Thorne','Chief Nursing Officer',
    'Nursing workforce matrix: Using a CTE, count Nurse Practitioners (NP) and Bachelor of Science in Nursing (BSN) nurses across Day and Night shifts. Return shift, NP count, BSN count, and total nurses.',
    'WITH nurse_matrix AS (...) SELECT shift, np_count, bsn_count, total_nurses.',['WITH CTE','GROUP BY','SUM CASE'],['shift','np_count','bsn_count','total_nurses'],
    "WITH nurse_matrix AS (SELECT shift, SUM(CASE WHEN certification_level = 'NP' THEN 1 ELSE 0 END) AS np_count, SUM(CASE WHEN certification_level = 'BSN' THEN 1 ELSE 0 END) AS bsn_count, COUNT(id) AS total_nurses FROM nurses GROUP BY shift) SELECT shift, np_count, bsn_count, total_nurses FROM nurse_matrix ORDER BY shift ASC;",'t',
    ['Group nurses by shift in CTE.','Pivot certification levels and calculate total nurses per shift.'],'Assesses credentialing mix across daytime and nocturnal nursing rosters.',45,8),

  q('hc-L5-072','healthcare',5,72,'advanced','Clinical Procedural Revenue Contribution by Medical Specialty (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Procedural service line economics: Using a CTE that joins medical procedures to departments and doctors, calculate total procedures and total procedural cost potential for each department. Return department name, procedure count, and total cost potential.',
    'WITH proc_rev AS (...) SELECT department_name, procedure_count, total_cost_potential.',['WITH CTE','INNER JOIN','GROUP BY','SUM'],['department_name','procedure_count','total_cost_potential'],
    "WITH proc_rev AS (SELECT d.name AS department_name, COUNT(p.id) AS procedure_count, ROUND(SUM(p.standard_cost), 2) AS total_cost_potential FROM departments d JOIN medical_procedures p ON d.id = p.department_id GROUP BY d.id, d.name) SELECT department_name, procedure_count, total_cost_potential FROM proc_rev ORDER BY total_cost_potential DESC;",'t',
    ['Join departments to procedures in CTE.','Compute procedure count and total standard_cost.'],'Highlights procedural contribution to department gross clinical margins.',45,8),

  q('hc-L5-073','healthcare',5,73,'advanced','Inpatient Admission Length of Stay and Discharge Velocity (CTE)','Dr. Sarah Patel','Head of Surgery',
    'Hospital bed throughput: Using a CTE, calculate average length of stay in days and total admissions count for each room type. Return room type, total admissions, and avg stay days.',
    'WITH room_adms AS (...) SELECT room_type, total_admissions, avg_stay_days.',['WITH CTE','INNER JOIN','GROUP BY','AVG','ROUND'],['room_type','total_admissions','avg_stay_days'],
    "WITH room_adms AS (SELECT r.room_type, COUNT(ia.id) AS total_admissions, ROUND(AVG(ia.discharge_date - ia.admission_date), 1) AS avg_stay_days FROM inpatient_admissions ia JOIN rooms r ON ia.room_id = r.id WHERE ia.discharge_date IS NOT NULL GROUP BY r.room_type) SELECT room_type, total_admissions, avg_stay_days FROM room_adms ORDER BY avg_stay_days DESC;",'t',
    ['Join admissions to rooms in CTE.','Compute admissions count and avg length of stay per room type.'],'Evaluates hospitalization durations across intensive care vs standard beds.',45,8),

  q('hc-L5-074','healthcare',5,74,'advanced','Payer Claim Approval Ratio and Settlement Turnaround Correlation (CTE)','Jordan Chen','Director of Billing',
    'Payer operational matrix: Using a CTE, calculate total claims, approved claims count, approval rate pct, and average settlement days for each insurance provider. Return insurance provider, total claims, approval rate pct, and avg settlement days.',
    'WITH payer_matrix AS (...) SELECT insurance_provider, total_claims, approval_rate_pct, avg_settlement_days.',['WITH CTE','GROUP BY','SUM CASE','AVG'],['insurance_provider','total_claims','approval_rate_pct','avg_settlement_days'],
    "WITH payer_matrix AS (SELECT insurance_provider, COUNT(id) AS total_claims, ROUND(SUM(CASE WHEN status = 'approved' THEN 1.0 ELSE 0.0 END) / COUNT(id) * 100.0, 1) AS approval_rate_pct, ROUND(AVG(settlement_days), 1) AS avg_settlement_days FROM insurance_claims GROUP BY insurance_provider) SELECT insurance_provider, total_claims, approval_rate_pct, avg_settlement_days FROM payer_matrix ORDER BY approval_rate_pct DESC, avg_settlement_days ASC;",'t',
    ['Compute claims count, approval percentage, and average settlement turnaround in CTE.','Select payer performance KPIs.'],'Correlates claims approval efficiency with adjudication turnaround velocity.',45,9),

  q('hc-L5-075','healthcare',5,75,'advanced','Patient Cumulative Outpatient and Inpatient Billing Burden (Multi-Stage CTE)','Jordan Chen','Director of Billing',
    'Comprehensive patient liability: Using a multi-stage CTE, calculate total billed charges, insurance covered, and remaining balance for each patient. Categorize patients with balance > $500 as High Burden. Return patient_id, total billed, patient balance, and liability category.',
    'WITH pt_billing AS (...) SELECT patient_id, total_billed, patient_balance, liability_category.',['WITH CTE','GROUP BY','SUM','CASE WHEN'],['patient_id','total_billed','patient_balance','liability_category'],
    "WITH pt_billing AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_billed, ROUND(SUM(patient_balance), 2) AS patient_balance FROM billing GROUP BY patient_id) SELECT patient_id, total_billed, patient_balance, CASE WHEN patient_balance >= 500.00 THEN 'High Burden' ELSE 'Standard' END AS liability_category FROM pt_billing ORDER BY patient_balance DESC;",'t',
    ['Sum total_charge and patient_balance per patient in CTE.','Classify balance liability in outer query.'],'Identifies patient accounts requiring financial counseling or hardship payment plans.',45,9),

  // 76–100: Boss / Capstone (Enterprise Hospital Consolidated P&L, Master Clinical Journeys, Executive Dashboards)
  q('hc-L5-076','healthcare',5,76,'boss','Hospital Master Clinical Service Line Revenue and Margin Model','Jordan Chen','Director of Billing',
    'Executive Board Briefing: Construct an enterprise clinical service line financial model across all departments. Combine total outpatient appointment revenue, total daily bed revenue from occupied rooms, and total medical procedures standard cost. Return department name, building, appointment revenue, bed revenue, procedure revenue, and total service line revenue.',
    'Multi-stage CTE integrating 3 revenue streams, summing total service line revenue.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','SUM','COALESCE'],['department_name','building','appointment_revenue','bed_revenue','procedure_revenue','total_service_line_revenue'],
    "WITH appt_rev AS (SELECT dept.id AS department_id, dept.name AS department_name, dept.building, ROUND(SUM(a.fee), 2) AS appt_revenue FROM departments dept JOIN doctors doc ON dept.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id WHERE a.status = 'completed' GROUP BY dept.id, dept.name, dept.building), bed_rev AS (SELECT department_id, ROUND(SUM(daily_rate), 2) AS bed_revenue FROM rooms WHERE is_occupied = TRUE GROUP BY department_id), proc_rev AS (SELECT department_id, ROUND(SUM(standard_cost), 2) AS proc_revenue FROM medical_procedures GROUP BY department_id) SELECT a.department_name, a.building, COALESCE(a.appt_revenue, 0.00) AS appointment_revenue, COALESCE(b.bed_revenue, 0.00) AS bed_revenue, COALESCE(p.proc_revenue, 0.00) AS procedure_revenue, ROUND(COALESCE(a.appt_revenue, 0.00) + COALESCE(b.bed_revenue, 0.00) + COALESCE(p.proc_revenue, 0.00), 2) AS total_service_line_revenue FROM appt_rev a LEFT JOIN bed_rev b ON a.department_id = b.department_id LEFT JOIN proc_rev p ON a.department_id = p.department_id ORDER BY total_service_line_revenue DESC;",'t',
    ['Compute revenue in 3 CTEs (appointments, rooms, procedures).','Join on department_id with COALESCE.','Sum all 3 streams into total_service_line_revenue.'],'Master hospital service line financial model integrating ambulatory visits, inpatient beds, and procedural throughput.',50,15),

  q('hc-L5-077','healthcare',5,77,'boss','Physician 360 Enterprise Clinical and Financial Productivity Index','Dr. Evelyn Reed','Chief Medical Officer',
    'Medical Executive Board Audit: Construct a 360-degree physician practice evaluation using multi-stage CTEs. For each doctor, calculate completed appointments, gross appointment revenue, total prescriptions authored, and total inpatient admissions managed. Return doctor name, specialty, completed visits, gross revenue, prescriptions count, and admissions count.',
    '4-stage CTE uniting doctor encounters across appointments, prescriptions, and admissions.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','COALESCE'],['name','specialty','completed_visits','gross_revenue','prescriptions_count','admissions_count'],
    "WITH appts AS (SELECT doctor_id, COUNT(id) AS completed_visits, ROUND(SUM(fee), 2) AS gross_revenue FROM appointments WHERE status = 'completed' GROUP BY doctor_id), rxs AS (SELECT doctor_id, COUNT(id) AS prescriptions_count FROM prescriptions GROUP BY doctor_id), adms AS (SELECT admitting_doctor_id, COUNT(id) AS admissions_count FROM inpatient_admissions GROUP BY admitting_doctor_id) SELECT d.name, d.specialty, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(a.gross_revenue, 0.00) AS gross_revenue, COALESCE(r.prescriptions_count, 0) AS prescriptions_count, COALESCE(ad.admissions_count, 0) AS admissions_count FROM doctors d LEFT JOIN appts a ON d.id = a.doctor_id LEFT JOIN rxs r ON d.id = r.doctor_id LEFT JOIN adms ad ON d.id = ad.admitting_doctor_id ORDER BY gross_revenue DESC, completed_visits DESC LIMIT 24;",'t',
    ['Aggregate encounters in 3 CTEs (appointments, prescriptions, admissions).','Join to doctors table with COALESCE.','Order by gross_revenue DESC LIMIT 24.'],'Comprehensive executive scorecard ranking clinical medical staff across clinical, pharmaceutical, and inpatient activities.',50,14),

  q('hc-L5-078','healthcare',5,78,'boss','Chief Medical Officer Patient Clinical Risk and Journey Audit','Dr. Evelyn Reed','Chief Medical Officer',
    'Master Patient Journey Audit: Identify patients who have navigated the entire clinical continuum — attending a completed appointment, receiving an ICD-10 diagnosis, undergoing a lab test with an abnormal flag, and having an inpatient admission or prescription. Return patient first name, last name, city, diagnoses count, lab count, and total billed hospital charges.',
    'Multi-stage CTE joining patients, diagnoses, lab results, and billing.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','SUM'],['first_name','last_name','city','diagnoses_count','abnormal_labs_count','total_hospital_billed'],
    "WITH pt_diags AS (SELECT patient_id, COUNT(id) AS diagnoses_count FROM diagnoses GROUP BY patient_id), pt_labs AS (SELECT patient_id, COUNT(id) AS abnormal_labs_count FROM patient_lab_results WHERE flag IN ('HIGH', 'LOW') GROUP BY patient_id), pt_billing AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_hospital_billed FROM billing GROUP BY patient_id) SELECT p.first_name, p.last_name, p.city, d.diagnoses_count, l.abnormal_labs_count, b.total_hospital_billed FROM patients p JOIN pt_diags d ON p.id = d.patient_id JOIN pt_labs l ON p.id = l.patient_id JOIN pt_billing b ON p.id = b.patient_id ORDER BY b.total_hospital_billed DESC LIMIT 15;",'t',
    ['Aggregate diagnoses, abnormal labs, and billing in 3 CTEs.','Join to patients table.','Order by total_hospital_billed DESC LIMIT 15.'],'Capstone executive patient complexity audit linking high clinical risk to aggregate health system financial charges.',50,15),

  q('hc-L5-079','healthcare',5,79,'boss','Hospital Accounts Receivable Aging and Contractual Yield Reconciliation','Jordan Chen','Director of Billing',
    'Financial reconciliation: Using a multi-stage CTE, calculate total billed charges, insurance covered, patient balance, and average claim settlement days for each health insurance provider. Return insurance provider, total billed, insurance covered, patient balance, and avg settlement days.',
    'Multi-stage CTE combining billing and claims metrics per payer.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','SUM','AVG'],['insurance_provider','total_billed','total_insurance_covered','total_patient_balance','avg_settlement_days'],
    "WITH billing_stats AS (SELECT p.insurance_provider, ROUND(SUM(b.total_charge), 2) AS total_billed, ROUND(SUM(b.insurance_covered), 2) AS total_insurance_covered, ROUND(SUM(b.patient_balance), 2) AS total_patient_balance FROM billing b JOIN patients p ON b.patient_id = p.id GROUP BY p.insurance_provider), claim_stats AS (SELECT insurance_provider, ROUND(AVG(settlement_days), 1) AS avg_settlement_days FROM insurance_claims GROUP BY insurance_provider) SELECT b.insurance_provider, b.total_billed, b.total_insurance_covered, b.total_patient_balance, COALESCE(c.avg_settlement_days, 0.0) AS avg_settlement_days FROM billing_stats b LEFT JOIN claim_stats c ON b.insurance_provider = c.insurance_provider ORDER BY b.total_billed DESC;",'t',
    ['Compute billing metrics in billing_stats CTE.','Compute claim settlement speed in claim_stats CTE.','Join on insurance_provider and order by total_billed DESC.'],'Executive payer balance sheet reconciling institutional revenue cycle performance with payer adjudication velocity.',50,14),

  q('hc-L5-080','healthcare',5,80,'boss','Inpatient 30-Day Readmission Rate and Financial Exposure Audit','Dr. Sarah Patel','Head of Surgery',
    'CMS readmission penalty and cost impact: Using a multi-stage CTE, identify all patients with a 30-day inpatient readmission, and calculate the total hospital billing charges incurred by each readmitted patient. Return patient first name, last name, readmission interval days, and total hospital charges.',
    'Multi-stage CTE with LAG() on admissions joined to patients and billing.',['WITH CTE','MULTI-STAGE CTE','LAG','PARTITION BY','INNER JOIN','GROUP BY','SUM'],['first_name','last_name','days_between','total_hospital_charges'],
    "WITH readms AS (SELECT patient_id, (admission_date - LAG(discharge_date, 1) OVER (PARTITION BY patient_id ORDER BY admission_date ASC)) AS days_between FROM inpatient_admissions), readm_pts AS (SELECT patient_id, MIN(days_between) AS days_between FROM readms WHERE days_between IS NOT NULL AND days_between <= 30 GROUP BY patient_id), pt_billing AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_hospital_charges FROM billing GROUP BY patient_id) SELECT p.first_name, p.last_name, r.days_between, b.total_hospital_charges FROM readm_pts r JOIN patients p ON r.patient_id = p.id JOIN pt_billing b ON p.id = b.patient_id ORDER BY b.total_hospital_charges DESC;",'t',
    ['Identify 30-day readmissions using LAG in readms CTE.','Join with patients and aggregate billing charges in pt_billing CTE.','Order by total_hospital_charges DESC.'],'Critical health system quality assurance metric quantifying readmission penalties and patient financial liabilities.',50,15),

  q('hc-L5-081','healthcare',5,81,'boss','Operating Room Surgical Throughput and Capacity Yield Model','Dr. Sarah Patel','Head of Surgery',
    'Surgical block optimization: Using a multi-stage CTE, calculate total procedural minutes, average procedure duration, total procedural cost potential, and procedure count for each clinical department. Return department name, building, floor, procedure count, total duration minutes, and total cost potential.',
    'CTE aggregating medical_procedures joined to departments.',['WITH CTE','INNER JOIN','GROUP BY','SUM','AVG'],['department_name','building','floor','procedure_count','total_duration_minutes','total_cost_potential'],
    "WITH proc_model AS (SELECT d.name AS department_name, d.building, d.floor, COUNT(p.id) AS procedure_count, SUM(p.duration_minutes) AS total_duration_minutes, ROUND(SUM(p.standard_cost), 2) AS total_cost_potential FROM departments d JOIN medical_procedures p ON d.id = p.department_id GROUP BY d.id, d.name, d.building, d.floor) SELECT department_name, building, floor, procedure_count, total_duration_minutes, total_cost_potential FROM proc_model ORDER BY total_cost_potential DESC;",'t',
    ['Aggregate procedures per department in CTE.','Select department_name, building, floor, procedure_count, total_duration_minutes, total_cost_potential.'],'Models operative block scheduling and procedural yield across surgical tower facilities.',50,12),

  q('hc-L5-082','healthcare',5,82,'boss','Chronic Care Management: Diabetic Patient Care Continuum Audit','Dr. Evelyn Reed','Chief Medical Officer',
    'Diabetic clinical pathway scorecard: Using multi-stage CTEs, identify all patients diagnosed with Type 2 Diabetes (E11.9). Determine whether they have a prescription for Glucophage, whether they had an A1c or metabolic lab test, and calculate their total hospital spend. Return patient first name, last name, has_prescription, has_lab, and total billed charges.',
    'Multi-stage CTE checking care pathway compliance for diabetic cohort.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','SUM CASE'],['first_name','last_name','has_prescription','has_lab','total_billed'],
    "WITH diab_pts AS (SELECT DISTINCT patient_id FROM diagnoses WHERE icd10_code = 'E11.9'), rx_check AS (SELECT DISTINCT patient_id FROM prescriptions WHERE medication_name = 'Glucophage'), lab_check AS (SELECT DISTINCT patient_id FROM patient_lab_results), bill_totals AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_billed FROM billing GROUP BY patient_id) SELECT p.first_name, p.last_name, (CASE WHEN r.patient_id IS NOT NULL THEN 'Yes' ELSE 'No' END) AS has_prescription, (CASE WHEN l.patient_id IS NOT NULL THEN 'Yes' ELSE 'No' END) AS has_lab, COALESCE(b.total_billed, 0.00) AS total_billed FROM diab_pts d JOIN patients p ON d.patient_id = p.id LEFT JOIN rx_check r ON d.patient_id = r.patient_id LEFT JOIN lab_check l ON d.patient_id = l.patient_id LEFT JOIN bill_totals b ON d.patient_id = b.patient_id ORDER BY total_billed DESC;",'t',
    ['Isolate diabetic patients in diab_pts CTE.','Check prescription and lab presence in separate CTEs.','Join to patients and billing.'],'Audits clinical quality protocol compliance for diabetes mellitus population health.',50,15),

  q('hc-L5-083','healthcare',5,83,'boss','Department Bed Census Monetization and Vacancy Cost Analysis','Marcus Thorne','Chief Nursing Officer',
    'Inpatient vacancy financial leakage: Using a multi-stage CTE, calculate total beds, occupied beds, vacant beds, daily realized revenue, and unrealized daily revenue lost to vacant beds per department. Return department name, total beds, occupied beds, vacant beds, realized revenue, and unrealized vacancy loss.',
    'Multi-stage CTE calculating occupied and vacant bed revenue deltas.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE'],['department_name','total_beds','occupied_beds','vacant_beds','realized_revenue','unrealized_vacancy_loss'],
    "WITH bed_census AS (SELECT d.name AS department_name, COUNT(r.id) AS total_beds, SUM(CASE WHEN r.is_occupied THEN 1 ELSE 0 END) AS occupied_beds, SUM(CASE WHEN NOT r.is_occupied THEN 1 ELSE 0 END) AS vacant_beds, ROUND(SUM(CASE WHEN r.is_occupied THEN r.daily_rate ELSE 0 END), 2) AS realized_revenue, ROUND(SUM(CASE WHEN NOT r.is_occupied THEN r.daily_rate ELSE 0 END), 2) AS unrealized_vacancy_loss FROM departments d JOIN rooms r ON d.id = r.department_id GROUP BY d.id, d.name) SELECT department_name, total_beds, occupied_beds, vacant_beds, realized_revenue, unrealized_vacancy_loss FROM bed_census ORDER BY unrealized_vacancy_loss DESC;",'t',
    ['Compute occupied and vacant bed metrics in CTE.','Select department_name, total_beds, occupied_beds, vacant_beds, realized_revenue, unrealized_vacancy_loss.'],'Quantifies financial capacity leakage from empty hospital beds across inpatient service lines.',50,12),

  q('hc-L5-084','healthcare',5,84,'boss','Physician Master Clinical Practice Profile (Multi-Specialty Benchmark)','Dr. Evelyn Reed','Chief Medical Officer',
    'Executive Medical Staff Benchmark: Using multi-stage CTEs, compute completed consultations, total visit fees, distinct medications prescribed, and severe diagnoses treated per doctor. Return doctor name, specialty, completed visits, gross revenue, distinct medications, and severe diagnoses.',
    '4-stage CTE linking doctor consultations, fees, medications, and severe diagnoses.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','COUNT DISTINCT'],['name','specialty','completed_visits','gross_revenue','distinct_medications','severe_diagnoses'],
    "WITH appts AS (SELECT doctor_id, COUNT(id) AS completed_visits, ROUND(SUM(fee), 2) AS gross_revenue FROM appointments WHERE status = 'completed' GROUP BY doctor_id), rxs AS (SELECT doctor_id, COUNT(DISTINCT medication_name) AS distinct_medications FROM prescriptions GROUP BY doctor_id), diags AS (SELECT a.doctor_id, COUNT(dg.id) AS severe_diagnoses FROM appointments a JOIN diagnoses dg ON a.id = dg.appointment_id WHERE dg.severity = 'Severe' GROUP BY a.doctor_id) SELECT d.name, d.specialty, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(a.gross_revenue, 0.00) AS gross_revenue, COALESCE(r.distinct_medications, 0) AS distinct_medications, COALESCE(dg.severe_diagnoses, 0) AS severe_diagnoses FROM doctors d LEFT JOIN appts a ON d.id = a.doctor_id LEFT JOIN rxs r ON d.id = r.doctor_id LEFT JOIN diags dg ON d.id = dg.doctor_id ORDER BY gross_revenue DESC, completed_visits DESC LIMIT 24;",'t',
    ['Compute metrics in 3 CTEs (appointments, prescriptions, diagnoses).','Join to doctors with COALESCE.','Order by gross_revenue DESC LIMIT 24.'],'Comprehensive medical staff benchmark integrating clinical revenue, formulary diversity, and case-mix acuity.',50,14),

  q('hc-L5-085','healthcare',5,85,'boss','Hospital Revenue Cycle Payer Adjudication and Denial Leakage Scorecard','Jordan Chen','Director of Billing',
    'Payer adjudication master audit: Using a 3-stage CTE, calculate total claim amount, approved amount, denied claim amount, and contractual write-off haircut per insurance provider. Return insurance provider, total claims, gross claimed, net approved, denied amount, and realization pct.',
    '3-stage CTE calculating payer metrics and contractual write-off percentages.',['WITH CTE','MULTI-STAGE CTE','GROUP BY','SUM','ROUND'],['insurance_provider','total_claims','gross_claimed','net_approved','denied_amount','realization_pct'],
    "WITH payer_totals AS (SELECT insurance_provider, COUNT(id) AS total_claims, ROUND(SUM(claim_amount), 2) AS gross_claimed, ROUND(SUM(approved_amount), 2) AS net_approved, ROUND(SUM(CASE WHEN status = 'denied' THEN claim_amount ELSE 0 END), 2) AS denied_amount FROM insurance_claims GROUP BY insurance_provider) SELECT insurance_provider, total_claims, gross_claimed, net_approved, denied_amount, ROUND(net_approved / NULLIF(gross_claimed, 0) * 100.0, 1) AS realization_pct FROM payer_totals ORDER BY gross_claimed DESC;",'t',
    ['Aggregate claim totals and denied amounts per payer in CTE.','Compute contractual realization percentage in outer query.'],'Master executive payer revenue cycle scorecard isolating claim rejection dollars and recovery yields.',50,13),

  q('hc-L5-086','healthcare',5,86,'boss','Hospital Senior Patient Longitudinal Clinical and Billing Ledger','Dr. Evelyn Reed','Chief Medical Officer',
    'Geriatric health economics: Using a 3-stage CTE, identify senior patients (born before 1965), and calculate their completed appointments count, total diagnoses recorded, and total hospital billing charges. Return patient first name, last name, date of birth, completed visits, diagnoses count, and total billed charges.',
    '3-stage CTE linking senior patients, visits, diagnoses, and billing.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','SUM'],['first_name','last_name','dob','completed_visits','diagnoses_count','total_hospital_billed'],
    "WITH sr_pts AS (SELECT id, first_name, last_name, dob FROM patients WHERE dob < '1965-01-01'), appts AS (SELECT patient_id, COUNT(id) AS completed_visits FROM appointments WHERE status = 'completed' GROUP BY patient_id), diags AS (SELECT patient_id, COUNT(id) AS diagnoses_count FROM diagnoses GROUP BY patient_id), bills AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_hospital_billed FROM billing GROUP BY patient_id) SELECT s.first_name, s.last_name, s.dob, COALESCE(a.completed_visits, 0) AS completed_visits, COALESCE(d.diagnoses_count, 0) AS diagnoses_count, COALESCE(b.total_hospital_billed, 0.00) AS total_hospital_billed FROM sr_pts s LEFT JOIN appts a ON s.id = a.patient_id LEFT JOIN diags d ON s.id = d.patient_id LEFT JOIN bills b ON s.id = b.patient_id ORDER BY total_hospital_billed DESC LIMIT 20;",'t',
    ['Filter senior cohort in sr_pts CTE.','Join with visits, diagnoses, and billing CTEs.','Order by total_hospital_billed DESC LIMIT 20.'],'Longitudinal clinical and financial master profile for senior hospital patient population.',50,14),

  q('hc-L5-087','healthcare',5,87,'boss','Department Operating Room Duration Capacity vs Nursing Shift Ratio','Dr. Sarah Patel','Head of Surgery',
    'Surgical operating room and nursing staffing alignment: Using a multi-stage CTE, calculate total procedural minutes and Day shift nurses staffed per department. Compute the procedural minutes per Day nurse ratio. Return department name, total procedural minutes, Day nurses count, and minutes per Day nurse.',
    'Multi-stage CTE joining procedures and nursing shifts per department.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','SUM','ARITHMETIC'],['department_name','total_procedural_minutes','day_nurses_count','minutes_per_day_nurse'],
    "WITH proc_mins AS (SELECT department_id, SUM(duration_minutes) AS total_procedural_minutes FROM medical_procedures GROUP BY department_id), nurse_staff AS (SELECT department_id, SUM(CASE WHEN shift = 'Day' THEN 1 ELSE 0 END) AS day_nurses_count FROM nurses GROUP BY department_id) SELECT d.name AS department_name, p.total_procedural_minutes, n.day_nurses_count, ROUND(p.total_procedural_minutes::NUMERIC / NULLIF(n.day_nurses_count, 0), 1) AS minutes_per_day_nurse FROM departments d JOIN proc_mins p ON d.id = p.department_id JOIN nurse_staff n ON d.id = n.department_id ORDER BY minutes_per_day_nurse DESC;",'t',
    ['Compute procedural minutes and day nurses in dual CTEs.','Join on department_id and calculate workload ratio.'],'Aligns operative surgical block scheduling with departmental daytime nursing resources.',50,12),

  q('hc-L5-088','healthcare',5,88,'boss','Comprehensive Pathology and Diagnostic Abnormality Profile per Specialty','Dr. Anthony Clark','Director of Pathology & Lab',
    'Specialty diagnostic surveillance: Using a multi-stage CTE, calculate total lab tests ordered and abnormal test flags recorded for patients treated by each doctor specialty. Return specialty, total tests ordered, abnormal flags count, and abnormal flag percentage.',
    'Multi-stage CTE joining doctors, appointments, patients, and lab results.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','SUM CASE'],['specialty','total_tests_ordered','abnormal_flags_count','abnormal_flag_pct'],
    "WITH spec_labs AS (SELECT d.specialty, COUNT(plr.id) AS total_tests_ordered, SUM(CASE WHEN plr.flag IN ('HIGH', 'LOW') THEN 1 ELSE 0 END) AS abnormal_flags_count FROM doctors d JOIN appointments a ON d.id = a.doctor_id JOIN patient_lab_results plr ON a.patient_id = plr.patient_id GROUP BY d.specialty) SELECT specialty, total_tests_ordered, abnormal_flags_count, ROUND(abnormal_flags_count::NUMERIC / NULLIF(total_tests_ordered, 0) * 100.0, 1) AS abnormal_flag_pct FROM spec_labs ORDER BY abnormal_flag_pct DESC;",'t',
    ['Join doctors to appointments and lab results in CTE.','Calculate abnormal percentage per specialty.'],'Surfaces medical specialties detecting the highest proportion of pathological biomarker abnormalities.',50,13),

  q('hc-L5-089','healthcare',5,89,'boss','Executive Hospital Inpatient Bed Capacity and Staffing Equilibrium','Marcus Thorne','Chief Nursing Officer',
    'Inpatient capacity equilibrium: Construct a comprehensive model combining total beds, occupied beds, Day nurses, and Night nurses for each department. Return department name, total beds, occupied beds, Day nurses, Night nurses, and beds per total nurse ratio.',
    'Multi-stage CTE aggregating rooms and nursing shifts per department.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','SUM CASE'],['department_name','total_beds','occupied_beds','day_nurses','night_nurses','beds_per_nurse_ratio'],
    "WITH bed_stats AS (SELECT department_id, COUNT(id) AS total_beds, SUM(CASE WHEN is_occupied THEN 1 ELSE 0 END) AS occupied_beds FROM rooms GROUP BY department_id), nurse_stats AS (SELECT department_id, SUM(CASE WHEN shift = 'Day' THEN 1 ELSE 0 END) AS day_nurses, SUM(CASE WHEN shift = 'Night' THEN 1 ELSE 0 END) AS night_nurses, COUNT(id) AS total_nurses FROM nurses GROUP BY department_id) SELECT d.name AS department_name, b.total_beds, b.occupied_beds, n.day_nurses, n.night_nurses, ROUND(b.total_beds::NUMERIC / NULLIF(n.total_nurses, 0), 2) AS beds_per_nurse_ratio FROM departments d JOIN bed_stats b ON d.id = b.department_id JOIN nurse_stats n ON d.id = n.department_id ORDER BY b.occupied_beds DESC;",'t',
    ['Compute bed metrics and nursing shifts in dual CTEs.','Calculate beds_per_nurse ratio.'],'Evaluates facility infrastructure and workforce staffing equilibrium across hospital divisions.',50,13),

  q('hc-L5-090','healthcare',5,90,'boss','Master Hospital Outpatient Fee Schedule Yield and Median Benchmark','Jordan Chen','Director of Billing',
    'Fee schedule optimization: Using a multi-stage CTE, calculate total completed visits, gross revenue, average visit fee, and identify the minimum and maximum visit fee for each medical specialty. Return specialty, completed visits, gross revenue, average fee, min fee, and max fee.',
    'CTE aggregating completed appointments per specialty with MIN, MAX, AVG, SUM.',['WITH CTE','INNER JOIN','GROUP BY','SUM','AVG','MIN','MAX'],['specialty','completed_visits','gross_revenue','avg_fee','min_fee','max_fee'],
    "WITH spec_fees AS (SELECT d.specialty, COUNT(a.id) AS completed_visits, ROUND(SUM(a.fee), 2) AS gross_revenue, ROUND(AVG(a.fee), 2) AS avg_fee, ROUND(MIN(a.fee), 2) AS min_fee, ROUND(MAX(a.fee), 2) AS max_fee FROM doctors d JOIN appointments a ON d.id = a.doctor_id WHERE a.status = 'completed' GROUP BY d.specialty) SELECT specialty, completed_visits, gross_revenue, avg_fee, min_fee, max_fee FROM spec_fees ORDER BY gross_revenue DESC;",'t',
    ['Aggregate completed visits, fees, and bounds per specialty in CTE.','Order by gross_revenue DESC.'],'Comprehensive outpatient fee schedule yield analysis for hospital executive leadership.',50,12),

  q('hc-L5-091','healthcare',5,91,'boss','Multimorbid Patient Polypharmacy and High-Dollar Inpatient Exposure','Dr. Evelyn Reed','Chief Medical Officer',
    'Complex case management: Identify patients diagnosed with at least 2 distinct conditions who also have at least 1 completed inpatient admission. Calculate their total hospital billing charges. Return patient first name, last name, distinct diagnoses count, and total billed charges.',
    'Multi-stage CTE filtering multimorbid admitted patients joined to billing.',['WITH CTE','MULTI-STAGE CTE','INNER JOIN','GROUP BY','SUM','COUNT DISTINCT'],['first_name','last_name','diagnoses_count','total_hospital_charges'],
    "WITH multi_pts AS (SELECT patient_id, COUNT(DISTINCT icd10_code) AS diagnoses_count FROM diagnoses GROUP BY patient_id HAVING COUNT(DISTINCT icd10_code) >= 2), adm_pts AS (SELECT DISTINCT patient_id FROM inpatient_admissions), bill_totals AS (SELECT patient_id, ROUND(SUM(total_charge), 2) AS total_hospital_charges FROM billing GROUP BY patient_id) SELECT p.first_name, p.last_name, m.diagnoses_count, b.total_hospital_charges FROM multi_pts m JOIN adm_pts a ON m.patient_id = a.patient_id JOIN patients p ON m.patient_id = p.id JOIN bill_totals b ON p.id = b.patient_id ORDER BY b.total_hospital_charges DESC;",'t',
    ['Filter multimorbid patients and admitted patients in separate CTEs.','Join with patients and billing totals.','Order by total_hospital_charges DESC.'],'Pins down high-cost multimorbid hospitalized patients requiring intense case management.',50,14),

  q('hc-L5-092','healthcare',5,92,'boss','Physician Clinical Workload and Schedule Adherence Decile Distribution','Dr. Evelyn Reed','Chief Medical Officer',
    'Medical staff activity deciles: Using a CTE, calculate total scheduled appointments for each doctor, and assign doctors into 10 workload deciles using NTILE(10). Return doctor name, specialty, total appointments, and workload decile.',
    'CTE calculating total appointments per doctor, then NTILE(10) in outer query.',['WITH CTE','NTILE','INNER JOIN','GROUP BY'],['name','specialty','total_appointments','workload_decile'],
    "WITH doc_appts AS (SELECT d.name, d.specialty, COUNT(a.id) AS total_appointments FROM doctors d JOIN appointments a ON d.id = a.doctor_id GROUP BY d.id, d.name, d.specialty) SELECT name, specialty, total_appointments, NTILE(10) OVER (ORDER BY total_appointments DESC) AS workload_decile FROM doc_appts ORDER BY workload_decile, total_appointments DESC;",'t',
    ['Compute total appointments per doctor in CTE.','Apply NTILE(10) OVER (ORDER BY total_appointments DESC) in outer query.'],'Ranks physicians into ten granular scheduling demand deciles.',50,10),

  q('hc-L5-093','healthcare',5,93,'boss','Department Procedural Cost Yield vs Outpatient Consultation Yield','Jordan Chen','Director of Billing',
    'Ambulatory vs procedural service mix: Using a multi-stage CTE, calculate completed appointment revenue and total medical procedures cost for each department. Return department name, appointment revenue, procedure cost potential, and combined clinical yield.',
    'Multi-stage CTE combining appointment fees and procedure costs per department.',['WITH CTE','MULTI-STAGE CTE','LEFT JOIN','GROUP BY','SUM','COALESCE'],['department_name','appointment_revenue','procedure_cost_potential','combined_clinical_yield'],
    "WITH appt_rev AS (SELECT dept.id AS department_id, dept.name AS department_name, ROUND(SUM(a.fee), 2) AS appt_revenue FROM departments dept JOIN doctors doc ON dept.id = doc.department_id JOIN appointments a ON doc.id = a.doctor_id WHERE a.status = 'completed' GROUP BY dept.id, dept.name), proc_rev AS (SELECT department_id, ROUND(SUM(standard_cost), 2) AS proc_cost FROM medical_procedures GROUP BY department_id) SELECT a.department_name, a.appt_revenue AS appointment_revenue, COALESCE(p.proc_cost, 0.00) AS procedure_cost_potential, ROUND(a.appt_revenue + COALESCE(p.proc_cost, 0.00), 2) AS combined_clinical_yield FROM appt_rev a LEFT JOIN proc_rev p ON a.department_id = p.department_id ORDER BY combined_clinical_yield DESC;",'t',
    ['Compute appointment revenue and procedure costs in dual CTEs.','Join on department_id and sum combined yield.'],'Analyzes departmental service line revenue diversification.',50,12),

  q('hc-L5-094','healthcare',5,94,'boss','Inpatient Admission Length of Stay and Discharge Disposition Scorecard','Dr. Sarah Patel','Head of Surgery',
    'Discharge disposition metrics: Using a CTE, calculate total admissions, average length of stay in days, and total bed days for each discharge disposition. Return discharge disposition, admissions count, avg stay days, and total bed days.',
    'CTE aggregating completed inpatient admissions per discharge disposition.',['WITH CTE','GROUP BY','AVG','SUM','ROUND'],['discharge_disposition','admissions_count','avg_stay_days','total_bed_days'],
    "WITH disp_metrics AS (SELECT discharge_disposition, COUNT(id) AS admissions_count, ROUND(AVG(discharge_date - admission_date), 1) AS avg_stay_days, SUM(discharge_date - admission_date) AS total_bed_days FROM inpatient_admissions WHERE discharge_date IS NOT NULL GROUP BY discharge_disposition) SELECT discharge_disposition, admissions_count, avg_stay_days, total_bed_days FROM disp_metrics ORDER BY total_bed_days DESC;",'t',
    ['Group completed admissions by discharge_disposition in CTE.','Compute admissions, avg stay, and total bed days.'],'Informs post-acute care coordination and skilled nursing facility transfer planning.',50,10),

  q('hc-L5-095','healthcare',5,95,'boss','Hospital Pharmacy Formulary High-Cost Medication Expenditure Breakdown','Dr. Evelyn Reed','Chief Medical Officer',
    'Formulary cost tiering: Using a CTE that joins prescriptions to medications, calculate total prescriptions and total formulary cost for medications costing >= $10.00 vs < $10.00. Return cost tier, total prescriptions, and total spend.',
    'CTE categorizing medications by unit cost, then aggregating spend.',['WITH CTE','INNER JOIN','GROUP BY','SUM','CASE WHEN'],['cost_tier','total_prescriptions','total_spend'],
    "WITH rx_costs AS (SELECT pr.id, m.unit_cost, (CASE WHEN m.unit_cost >= 10.00 THEN 'High Cost (>= $10)' ELSE 'Standard (< $10)' END) AS cost_tier FROM prescriptions pr JOIN medications m ON pr.medication_name = m.name) SELECT cost_tier, COUNT(id) AS total_prescriptions, ROUND(SUM(unit_cost), 2) AS total_spend FROM rx_costs GROUP BY cost_tier ORDER BY total_spend DESC;",'t',
    ['Categorize medications by unit cost in CTE.','Aggregate prescription counts and total spend.'],'Analyzes pharmacy acquisition budget concentration across expensive formulary agents.',50,10),

  q('hc-L5-096','healthcare',5,96,'boss','Hospital Payer Claims Adjudication Velocity Decile Distribution (NTILE CTE)','Jordan Chen','Director of Billing',
    'Claim payment speed deciles: Using a CTE, calculate average settlement days for approved claims per insurance provider, and assign providers to speed tiers. Return insurance provider, approved claims count, average settlement days, and speed rank.',
    'CTE calculating settlement speed, then ranking in outer query.',['WITH CTE','GROUP BY','AVG','ROUND','ORDER BY'],['insurance_provider','approved_claims','avg_settlement_days','speed_rank'],
    "WITH payer_speed AS (SELECT insurance_provider, COUNT(id) AS approved_claims, ROUND(AVG(settlement_days), 1) AS avg_settlement_days, DENSE_RANK() OVER (ORDER BY AVG(settlement_days) ASC) AS speed_rank FROM insurance_claims WHERE status = 'approved' GROUP BY insurance_provider) SELECT insurance_provider, approved_claims, avg_settlement_days, speed_rank FROM payer_speed ORDER BY speed_rank;",'t',
    ['Compute avg settlement days and rank with DENSE_RANK() in CTE.','Select carrier speed rankings.'],'Ranks health insurance carriers by claims reimbursement velocity.',50,10),

  q('hc-L5-097','healthcare',5,97,'boss','Department Nursing Shift Coverage and NP Staffing Ratio','Marcus Thorne','Chief Nursing Officer',
    'Advanced practice nursing ratio: Using a CTE, calculate total nurses, Nurse Practitioners (NP) count, and NP staffing percentage for each department. Return department name, total nurses, NP count, and NP percentage.',
    'CTE aggregating nurses per department and computing NP percentage.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE','ROUND'],['department_name','total_nurses','np_count','np_percentage'],
    "WITH dept_nurses AS (SELECT d.name AS department_name, COUNT(n.id) AS total_nurses, SUM(CASE WHEN n.certification_level = 'NP' THEN 1 ELSE 0 END) AS np_count FROM departments d JOIN nurses n ON d.id = n.department_id GROUP BY d.id, d.name) SELECT department_name, total_nurses, np_count, ROUND(np_count::NUMERIC / NULLIF(total_nurses, 0) * 100.0, 1) AS np_percentage FROM dept_nurses ORDER BY np_percentage DESC, total_nurses DESC;",'t',
    ['Compute total nurses and NP count per department in CTE.','Calculate NP percentage.'],'Evaluates advanced clinical nursing deployment across hospital units.',50,10),

  q('hc-L5-098','healthcare',5,98,'boss','Comprehensive Pathology Abnormal Diagnostic Flag Rate by Category','Dr. Anthony Clark','Director of Pathology & Lab',
    'Laboratory surveillance scorecard: Using a multi-stage CTE, calculate total tests performed, abnormal results count, and abnormal flag percentage for each pathology category. Return category, total tests, abnormal count, and abnormal pct.',
    'Multi-stage CTE computing test volumes and abnormal percentages per category.',['WITH CTE','INNER JOIN','GROUP BY','SUM CASE','ROUND'],['category','total_tests','abnormal_count','abnormal_pct'],
    "WITH lab_cats AS (SELECT lt.category, COUNT(plr.id) AS total_tests, SUM(CASE WHEN plr.flag IN ('HIGH', 'LOW') THEN 1 ELSE 0 END) AS abnormal_count FROM lab_tests lt JOIN patient_lab_results plr ON lt.id = plr.test_id GROUP BY lt.category) SELECT category, total_tests, abnormal_count, ROUND(abnormal_count::NUMERIC / NULLIF(total_tests, 0) * 100.0, 1) AS abnormal_pct FROM lab_cats ORDER BY abnormal_pct DESC;",'t',
    ['Join lab_tests to patient_lab_results in CTE.','Compute abnormal percentage per category.'],'Highlights pathology divisions detecting elevated disease activity.',50,10),

  q('hc-L5-099','healthcare',5,99,'boss','Hospital Accounts Receivable Uncollected Balances Aging Portfolio','Jordan Chen','Director of Billing',
    'Aging receivables summary: Using a CTE, calculate total vouchers, total billed charges, insurance covered, and remaining patient balance owed for overdue billing vouchers across patient insurance providers. Return insurance provider, overdue vouchers, total billed, insurance covered, and overdue balance.',
    'CTE filtering overdue billing records joined to patients.',['WITH CTE','INNER JOIN','WHERE','GROUP BY','SUM'],['insurance_provider','overdue_vouchers','total_billed','total_insurance_covered','overdue_balance'],
    "WITH overdue_ar AS (SELECT p.insurance_provider, COUNT(b.id) AS overdue_vouchers, ROUND(SUM(b.total_charge), 2) AS total_billed, ROUND(SUM(b.insurance_covered), 2) AS total_insurance_covered, ROUND(SUM(b.patient_balance), 2) AS overdue_balance FROM billing b JOIN patients p ON b.patient_id = p.id WHERE b.status = 'overdue' GROUP BY p.insurance_provider) SELECT insurance_provider, overdue_vouchers, total_billed, total_insurance_covered, overdue_balance FROM overdue_ar ORDER BY overdue_balance DESC;",'t',
    ['Join overdue billing to patients in CTE.','Aggregate charges, insurance covered, and patient balance per provider.'],'Profiles delinquency exposure and bad-debt risk by insurance carrier.',50,11),

  q('hc-L5-100','healthcare',5,100,'boss','Chief Executive Officer Hospital Enterprise Master Operational & Financial Summary','Dr. Evelyn Reed','Chief Medical Officer',
    'Executive Board Comprehensive Hospital State-of-the-System: Construct an all-encompassing enterprise CTE model uniting hospital operations. Calculate: (1) Total completed outpatient appointments, (2) Total outpatient fee revenue, (3) Total completed inpatient admissions, (4) Total inpatient bed days, (5) Total hospital billing charges across all vouchers, and (6) Total patient balance uncollected. Return total completed visits, outpatient fee revenue, inpatient admissions count, inpatient bed days, total billed charges, and total patient balance owed.',
    '6-stage unified enterprise CTE synthesizing hospital-wide operational and financial KPIs.',['WITH CTE','MULTI-STAGE CTE','SUM','COUNT'],['total_completed_visits','outpatient_fee_revenue','inpatient_admissions_count','inpatient_bed_days','total_billed_charges','total_patient_balance_owed'],
    "WITH appt_summary AS (SELECT COUNT(id) AS total_completed_visits, ROUND(SUM(fee), 2) AS outpatient_fee_revenue FROM appointments WHERE status = 'completed'), adm_summary AS (SELECT COUNT(id) AS inpatient_admissions_count, SUM(discharge_date - admission_date) AS inpatient_bed_days FROM inpatient_admissions WHERE discharge_date IS NOT NULL), bill_summary AS (SELECT ROUND(SUM(total_charge), 2) AS total_billed_charges, ROUND(SUM(patient_balance), 2) AS total_patient_balance_owed FROM billing) SELECT a.total_completed_visits, a.outpatient_fee_revenue, ad.inpatient_admissions_count, ad.inpatient_bed_days, b.total_billed_charges, b.total_patient_balance_owed FROM appt_summary a CROSS JOIN adm_summary ad CROSS JOIN bill_summary b;",'f',
    ['Compute outpatient KPIs in appt_summary CTE.','Compute inpatient KPIs in adm_summary CTE.','Compute revenue cycle KPIs in bill_summary CTE.','CROSS JOIN to produce a single executive dashboard row.'],'Grand capstone executive enterprise state-of-the-hospital model uniting clinical throughput, inpatient bed utilization, and gross institutional revenue cycle metrics.',50,15)
